// a = Index der richtigen Antwort (Optionen werden beim Spielen gemischt)
const QUESTIONS = [
// ---------- Grundlagen ----------
{t:"intro", q:"Was unterscheidet den Kernel Mode vom User Mode?", o:["Kernel Mode: alle Instruktionen erlaubt, voller Hardwarezugriff","User Mode: alle Instruktionen erlaubt, aber kein Zugriff auf den Kernel","Kernel Mode: nur privilegierte Instruktionen, keine normalen Rechenbefehle","User Mode: voller Hardwarezugriff, aber nur für einen Prozess gleichzeitig"], a:0, e:"User Mode: nur eine Teilmenge der Instruktionen, reduzierte Funktionalität. Kernel Mode: kompletter Hardwarezugriff, alle Instruktionen möglich. Alles Kritische ist im User Mode verboten."},
{t:"intro", q:"Was ist die Hauptaufgabe eines Betriebssystems?", o:["Hässliche Hardware-Schnittstellen in schöne Abstraktionen verwandeln","Anwendungen direkten, ungefilterten Zugriff auf die Hardware geben","Möglichst viele Hardwaredetails an die Anwendungen durchreichen","Für jede Anwendung eine eigene, angepasste Hardware-Schnittstelle bauen"], a:0, e:"Das OS macht aus der „hässlichen Schnittstelle“ der Hardware eine „schöne Schnittstelle“ für Anwendungen, bietet standardisierte Interfaces und orchestriert häufig genutzte Funktionen."},
{t:"intro", q:"Was gilt, wenn man in der Speicherhierarchie von Registern Richtung Magnetband nach unten geht?", o:["Kosten pro Bit sinken, Kapazität und Zugriffszeit steigen","Kosten pro Bit sinken, Kapazität steigt, Zugriffszeit sinkt","Kosten pro Bit steigen, Kapazität steigt, Zugriffszeit steigt","Kosten pro Bit steigen, Kapazität sinkt, Zugriffshäufigkeit steigt"], a:0, e:"Nach unten: sinkende Kosten pro Bit, steigende Kapazität, steigende Zugriffszeit und sinkende Häufigkeit des Zugriffs durch den Prozessor."},
{t:"intro", q:"Was besagt das Lokalitätsprinzip (Principle of Locality)?", o:["Zugriffe häufen sich zeitlich und räumlich auf wenige Speicherbereiche","Daten werden immer an der physisch nächstgelegenen Speicherstelle abgelegt","Jeder Prozess darf nur auf seinen eigenen, lokalen Speicher zugreifen","Häufig genutzte Programme werden dauerhaft im Hauptspeicher gehalten"], a:0, e:"Programme greifen in kurzer Zeit wiederholt auf dieselben (zeitlich) bzw. benachbarte (räumlich) Adressen zu. Deshalb lohnt sich ein kleiner, schneller Cache: Er hält genau diese Bereiche und trifft trotzdem die meisten Zugriffe."},
{t:"intro", q:"Welche Aussage über den Cache ist richtig?", o:["Er ist für das OS unsichtbar und nutzt das Lokalitätsprinzip","Er wird vom OS verwaltet und nutzt das Lokalitätsprinzip","Er ist für das OS unsichtbar und speichert nur Instruktionen","Er wird vom OS verwaltet und ersetzt teilweise den Hauptspeicher"], a:0, e:"Cache: für das OS unsichtbar, interagiert mit anderer Speicherverwaltungs-Hardware und nutzt das Principle of Locality mit kleinem, schnellem Speicher."},
{t:"intro", q:"Welche Stufen hat der Instruktionszyklus mit Interrupts (in dieser Reihenfolge)?", o:["Fetch → Execute → Interrupt","Fetch → Interrupt → Execute","Interrupt → Fetch → Execute","Execute → Fetch → Interrupt"], a:0, e:"Fetch Stage, Execute Stage, Interrupt Stage: Nach jeder Ausführung wird (bei aktivierten Interrupts) geprüft, ob ein Interrupt vorliegt, und ggf. der Interrupt Handler gestartet."},
{t:"intro", q:"Was enthält der Program Counter (PC)?", o:["Die Adresse der nächsten Instruktion","Die gerade geholte Instruktion selbst","Die Adresse des aktuellen Datenworts","Das Zwischenergebnis der letzten Operation"], a:0, e:"PC = Adresse der nächsten Instruktion. Die geholte Instruktion selbst landet im IR (Instruction Register), Daten im Akkumulator (AC)."},
{t:"intro", q:"Im Beispiel: Speicher 940 = 3, 941 = 2. Programm: 1940 (Load AC aus 940), 5941 (Add 941 zu AC), 2941 (Store AC nach 941). Was steht danach in 941?", o:["5","2","3","6"], a:0, e:"AC = 3, dann 3 + 2 = 5, dann wird AC nach 941 geschrieben → 941 enthält 5."},
{t:"intro", q:"Welches Segment eines Prozesses liegt bei den niedrigsten Adressen (0000)?", o:["Text","Stack","Data","Gap"], a:0, e:"Von unten nach oben: Text (Code) bei 0000, dann Data, dann eine Lücke (Gap), oben bei FFFF der Stack, der nach unten wächst."},
{t:"intro", q:"Was ist ein Systemaufruf (System Call)?", o:["Eine kontrollierte Anfrage eines Programms an den Kernel, per Trap in den Kernel Mode","Ein normaler Funktionsaufruf in eine Bibliothek, der komplett im User Mode bleibt","Ein Hardware-Signal eines Geräts, das die CPU über ein Ereignis informiert","Ein Befehl, mit dem ein Programm dauerhaft in den Kernel Mode wechselt"], a:0, e:"Programme dürfen Kritisches (I/O, Speicher, Prozesse) nicht selbst tun. Sie legen Parameter in Register (bei read(): Code in RAX, fd in RDI …) und lösen einen Trap aus; der Kernel prüft und erledigt die Anfrage und kehrt in den User Mode zurück."},
{t:"intro", q:"Was passiert beim „Mounten“ eines USB-Laufwerks?", o:["Sein Dateisystem wird in den bestehenden Verzeichnisbaum eingehängt","Sein Dateisystem ersetzt das bisherige Root-Verzeichnis vollständig","Seine Dateien werden in ein neues Verzeichnis auf der Festplatte kopiert","Sein Dateisystem wird in das Format des Root-Dateisystems umgewandelt"], a:0, e:"Vorher getrennte Bäume; nach dem Mounting hängt der Baum des USB-Laufwerks (x, y) unter einem Verzeichnis des Root-Dateisystems."},
{t:"intro", q:"Was kennzeichnet einen Multicore-Prozessor (Chip Multiprocessor)?", o:["Mehrere vollständige Kerne auf einem Die, oft mit gemeinsamem L3-Cache","Mehrere vollständige Kerne auf getrennten Chips mit gemeinsamem L1-Cache","Ein Kern mit mehreren Rechenwerken, die sich einen Program Counter teilen","Mehrere Kerne auf einem Die, die sich alle ein gemeinsames Rechenwerk teilen"], a:0, e:"Zwei oder mehr Cores auf einem Stück Silizium; jeder Core hat alle Komponenten eines Prozessors. Beispiel i7-5960X: je 32 kB L1-I/L1-D, 256 kB L2 pro Core, 20 MB geteilter L3."},
{t:"intro", q:"Was ist ein Batch-System?", o:["Jobs werden gesammelt und ohne Benutzerinteraktion nacheinander abgearbeitet","Mehrere Benutzer arbeiten interaktiv und gleichzeitig an einem Rechner","Aufgaben müssen garantiert innerhalb fester Zeitschranken fertig sein","Mehrere vernetzte Rechner erscheinen dem Nutzer als ein einziges System"], a:0, e:"Historische Batch-Systeme: Ein Job bestand aus Lochkarten mit Steuerkarten ($JOB, $FORTRAN, $LOAD, $RUN, $END), Programm und Daten. Ziel: hoher Durchsatz, keine Interaktion."},

// ---------- OS-Strukturen ----------
{t:"oss", q:"Was kennzeichnet ein monolithisches Betriebssystem?", o:["Das ganze OS läuft als ein großes Programm im Kernel Mode","Nur ein minimaler Kern läuft im Kernel Mode, der Rest als Prozesse","Das OS besteht aus Schichten, die nur die jeweils untere nutzen","Jeder Dienst des OS läuft in einer eigenen virtuellen Maschine"], a:0, e:"Monolithisch: Alle Prozeduren sind zu einem Programm gebunden und dürfen sich gegenseitig aufrufen – typischer Aufbau: Main Procedure → Service Procedures → Utility Procedures. Schnell, aber ein Fehler kann das ganze System treffen."},
{t:"oss", q:"Was ist ein Type-1-Hypervisor?", o:["Er läuft direkt auf der Hardware","Er läuft als Anwendung auf einem Host-OS","Er läuft als Kernelmodul im Gast-OS","Er läuft nur mit paravirtualisierten Gästen"], a:0, e:"Type 1: direkt auf der Hardware (z. B. ESXi, Xen, Hyper-V). Type 2: läuft auf einem Host-Betriebssystem (z. B. VirtualBox, UTM)."},
{t:"oss", q:"Wozu dient die HAL (Hardware Abstraction Layer) bei Windows?", o:["Sie kapselt Hardwaredetails, damit der Kernel hardwareunabhängig bleibt","Sie stellt Anwendungen eine einheitliche Programmierschnittstelle bereit","Sie verteilt die Rechenzeit der CPU auf die einzelnen Threads","Sie übersetzt Gerätebefehle direkt in Systemaufrufe der Anwendungen"], a:0, e:"Die HAL ist die unterste Schicht über der Hardware: Plattformspezifisches (Interrupt-Controller, Timer, Busse) steckt dort, der restliche Kernel bleibt portabel."},
{t:"oss", q:"Was ist bei Windows ein „Fiber“?", o:["Eine Ausführungseinheit, die die Anwendung selbst manuell scheduled","Eine Ausführungseinheit, die der Kernel mit höchster Priorität scheduled","Ein Objekt, das mehrere Prozesse gruppiert und gemeinsam verwaltet","Eine Sammlung von Worker-Threads für asynchrone Callbacks"], a:0, e:"Windows: Job = Gruppe von Prozessen, Process = Ressourcen, Thread = Ausführungseinheit, Fiber = manuell von der App geschedulte Einheit; Thread Pool = Sammlung von Worker-Threads."},
{t:"oss", q:"Was ist ein Microkernel?", o:["Ein minimaler Kern im Kernel Mode; Treiber und Dienste laufen als User-Prozesse","Ein besonders kleiner Kernel, der ganz ohne Kernel Mode auskommt","Ein Kernel, in dem alle Treiber und Dienste im Kernel Mode laufen","Ein Kernel, der nur auf Mikrocontrollern eingesetzt werden kann"], a:0, e:"Im Kernel bleibt nur das Nötigste (z. B. IPC, Scheduling, Speicher-Grundfunktionen). Stürzt ein Treiber ab, reißt er nicht das ganze System mit – dafür kostet die Kommunikation über Nachrichten Zeit."},
{t:"oss", q:"Was ist eine API wie die Win32-API?", o:["Eine Programmierschnittstelle, über die Anwendungen OS-Dienste nutzen","Eine Schicht, die den Kernel von hardwarespezifischen Details trennt","Ein Treibermodell, über das Geräte direkt mit Anwendungen sprechen","Eine Sammlung von Systemprozessen, die beim Booten gestartet werden"], a:0, e:"Win32: „Eine API für alle Versionen“ – Anwendungen rufen API-Funktionen auf, ohne Kernel-Interna zu kennen. Die API setzt die Aufrufe intern in Systemaufrufe um, und Programme laufen auf allen Windows-Versionen."},
{t:"oss", q:"Was macht Android, wenn RAM knapp wird und z. B. nach E-Mail die Kamera gestartet wurde?", o:["Es beendet den nun im Hintergrund liegenden E-Mail-Prozess","Es lagert den E-Mail-Prozess per Swapping auf den Flash aus","Es pausiert die Kamera, bis der E-Mail-Prozess fertig ist","Es teilt den RAM zu gleichen Teilen auf beide Prozesse auf"], a:0, e:"Beispiel aus den Folien: „Der E-Mail-Prozess wird entfernt, um RAM freizugeben“ – Prozesse mit niedriger Präzedenz werden beendet."},

// ---------- Prozesse ----------
{t:"proc", q:"Was ist ein Prozess?", o:["Ein Programm in Ausführung","Ein Programm auf der Festplatte","Ein Thread ohne eigenen Stack","Eine Sammlung von Systemaufrufen"], a:0, e:"Ein Prozess ist ein Programm in Ausführung, eine Instanz eines Programms, eine auf einem Prozessor ausführbare Einheit."},
{t:"proc", q:"Welcher Übergang existiert im 3-Zustands-Modell NICHT?", o:["Blocked → Running","Running → Blocked","Ready → Running","Blocked → Ready"], a:0, e:"Übergänge: 1 Running→Blocked (wartet auf Input), 2 Running→Ready (Scheduler wählt anderen), 3 Ready→Running (Scheduler wählt diesen), 4 Blocked→Ready (Input verfügbar). Ein blockierter Prozess muss erst Ready werden."},
{t:"proc", q:"Welche Zustände hat das 5-Zustands-Modell?", o:["New, Ready, Running, Blocked, Exit","New, Ready, Running, Suspended, Exit","Ready, Running, Blocked, Suspended, Exit","New, Ready, Running, Waiting, Zombie"], a:0, e:"Five-State Model: New –Admit→ Ready –Dispatch→ Running –Release→ Exit; Running –Timeout→ Ready; Running –Event Wait→ Blocked –Event Occurs→ Ready."},
{t:"proc", q:"Welcher Übergang heißt im 5-Zustands-Modell „Timeout“?", o:["Running → Ready","Ready → Running","Running → Blocked","Blocked → Ready"], a:0, e:"Timeout: Zeitscheibe abgelaufen, der Prozess geht von Running zurück nach Ready. Ready → Running heißt Dispatch, Running → Blocked Event Wait, Blocked → Ready Event Occurs."},
{t:"proc", q:"Was enthält ein Process Control Block (PCB) NICHT?", o:["Den kompletten Programmcode des Prozesses","Identifier, State und Priority","Program Counter und Memory Pointers","I/O-Status und Accounting-Informationen"], a:0, e:"PCB: Identifier, State, Priority, Program Counter, Memory Pointers, Context Data, I/O Status, Accounting. Der Programmcode gehört zum Process Image, nicht in den PCB."},
{t:"proc", q:"Was ist der Dispatcher?", o:["Ein kleines Programm, das die CPU von einem Prozess zum nächsten umschaltet","Ein kleines Programm, das neue Prozesse zum System zulässt","Die Liste der Instruktionen, die ein Prozess ausgeführt hat","Eine Tabelle, die alle wartenden Prozesse nach Priorität sortiert"], a:0, e:"Dispatcher = kleines Programm zum Umschalten zwischen Prozessen. Trace = Folge der ausgeführten Instruktionen eines Prozesses. Zulassung = Long-Term Scheduling."},
{t:"proc", q:"Was bedeutet „Suspension“ eines Prozesses?", o:["Er wird (teilweise) aus dem RAM auf die Platte ausgelagert","Er wird beendet und sein PCB aus der Prozesstabelle gelöscht","Er wartet im RAM auf ein I/O-Ereignis (Blocked)","Er bekommt vorübergehend die niedrigste Priorität"], a:0, e:"Swapping: Ist kein Prozess im RAM Ready, lagert das OS einen blockierten Prozess in eine Suspend Queue auf die Platte aus und holt einen anderen herein."},
{t:"proc", q:"Was ist ein Kontextwechsel (Context Switch)?", o:["Den Zustand des laufenden Prozesses sichern und den eines anderen laden","Den laufenden Prozess vom User Mode in den Kernel Mode umschalten","Einen Prozess aus dem Hauptspeicher auf die Festplatte auslagern","Einen neuen Prozess als Kopie des Elternprozesses erzeugen"], a:0, e:"Register, PC usw. werden im PCB gesichert, der PCB in die passende Queue verschoben, der nächste Prozess ausgewählt und sein Kontext geladen. Ein reiner Mode Switch (User → Kernel) ist dagegen billiger und wechselt den Prozess nicht."},
{t:"proc", q:"Was versteht man unter dem Process Image?", o:["Alles, was zu einem Prozess gehört: Programm, Daten, Stack und PCB","Nur der Maschinencode eines Programms, wie er auf der Platte liegt","Eine Momentaufnahme der CPU-Register beim letzten Kontextwechsel","Die Tabelle, in der das OS alle laufenden Prozesse verwaltet"], a:0, e:"Process Image = User Data + User Program + Stack + Process Control Block. Die Primary Process Table des OS verweist auf jedes Process Image."},
{t:"proc", q:"Was gibt die Prozesserzeugung an den Kindprozess zurück?", o:["0","Die PID des Elternprozesses","Die eigene PID","-1"], a:0, e:"Schritt 6 der Prozesserzeugung: Die ID des Kindes wird an den Elternprozess zurückgegeben, an den Kindprozess der Wert 0."},
{t:"proc", q:"Warum erhöht das OS bei der Prozesserzeugung die Zähler der offenen Dateien des Elternprozesses?", o:["Weil das Kind diese Dateien nun mitbenutzt","Weil das Kind eigene Kopien aller Dateien erhält","Weil der Elternprozess die Dateien jetzt schließt","Weil das OS die Größe der Dateien neu berechnet"], a:0, e:"Das Kind erbt die offenen Dateien des Elternprozesses. Der Zähler zeigt, wie viele Prozesse eine Datei geöffnet haben – erst bei 0 kann sie wirklich geschlossen werden."},
{t:"proc", q:"Wie hängt die CPU-Auslastung mit I/O-Wartezeit zusammen?", o:["Weniger I/O-Wartezeit → weniger Prozesse für hohe Auslastung nötig","Mehr I/O-Wartezeit → weniger Prozesse für hohe Auslastung nötig","Weniger I/O-Wartezeit → mehr Prozesse für hohe Auslastung nötig","Die I/O-Wartezeit hat keinen Einfluss, nur die Prozessanzahl zählt"], a:0, e:"Die CPU-Auslastung hängt von Prozessanzahl und I/O-Wartezeit ab: Bei wenig I/O-Wait reichen weniger Prozesse für eine hohe Auslastung."},
{t:"proc", q:"Was versteht man unter Multiprogramming?", o:["Mehrere Programme im Speicher; wartet eins auf I/O, rechnet ein anderes","Ein Programm wird in mehrere Teile zerlegt, die parallel laufen","Mehrere Prozessoren führen gleichzeitig dasselbe Programm aus","Ein Programm wird für mehrere Plattformen gleichzeitig übersetzt"], a:0, e:"Prozesse ermöglichen Multiprogramming: Die CPU wird nicht verschwendet, solange ein Prozess auf I/O wartet. Darauf bauen auch Time-Sharing und Echtzeit-Transaktionssysteme auf."},

// ---------- Threads ----------
{t:"thr", q:"Was teilen sich alle Threads eines Prozesses?", o:["Adressraum, globale Variablen, offene Dateien","Program Counter, Register, offene Dateien","Stack, globale Variablen, offene Dateien","Adressraum, Register, Zustand"], a:0, e:"Geteilt: Address space, globale Variablen, offene Dateien, Kindprozesse, Signale/Alarme, Accounting. Pro Thread: PC, Register, Stack, State."},
{t:"thr", q:"Was hat jeder Thread für sich allein?", o:["Program Counter, Register, Stack, Zustand","Program Counter, Register, offene Dateien","Adressraum, Stack, Zustand","Globale Variablen, Stack, Register"], a:0, e:"Deshalb sind Threads „leichtgewichtig“: Sie brauchen nur PC, Register, Stack und State – den Rest teilen sie mit dem Prozess."},
{t:"thr", q:"Was ist ein Nachteil von User-Level Threads (ULT)?", o:["Ein blockierender Syscall blockiert den ganzen Prozess","Jeder Thread-Wechsel erfordert einen Mode Switch","Sie funktionieren nur auf Betriebssystemen mit Thread-Support","Die Anwendung kann keinen eigenen Scheduling-Algorithmus wählen"], a:0, e:"ULT: Kernel kennt die Threads nicht. Vorteile: kein Mode Switch, app-spezifisches Scheduling, läuft auf jedem OS. Nachteile: blockierende Syscalls blockieren alles; kein echter Parallelismus."},
{t:"thr", q:"Was ist ein Vorteil von Kernel-Level Threads (KLT)?", o:["Threads eines Prozesses können parallel auf mehreren CPUs laufen","Thread-Wechsel innerhalb eines Prozesses brauchen keinen Mode Switch","Sie laufen auch auf Betriebssystemen ohne Thread-Unterstützung","Die Anwendung bestimmt den Scheduling-Algorithmus komplett selbst"], a:0, e:"KLT: Kernel kann Threads eines Prozesses parallel schedulen und bei Blockade einen anderen Thread wählen. Nachteil: Mode Switch in den Kernel bei jedem Thread-Wechsel."},
{t:"thr", q:"Bei User-Level Threads (Kernel wählt Prozesse, Runtime wählt Threads): Welche Reihenfolge ist NICHT möglich?", o:["A1, B1, A2, B2, A3, B3","A1, A2, A3, A1, A2, A3","A1, A2, A3, B1, B2, B3","A1, A1, A2, A3, B1, B2"], a:0, e:"Bei ULT wechselt der Kernel nur nach einer Zeitscheibe zwischen Prozessen – ein Wechsel A1→B1→A2 pro Thread ist nicht möglich. Bei KLT ist auch A1, B1, A2, B2 … möglich."},
{t:"thr", q:"Amdahls Gesetz: 90 % des Codes ist parallelisierbar (f = 0,9). Maximaler Speedup bei unendlich vielen Prozessoren?", o:["10","90","9","unendlich"], a:0, e:"Speedup = 1 / ((1−f) + f/N). Für N → ∞: 1 / (1−f) = 1 / 0,1 = 10. Schon kleine serielle Anteile begrenzen den Speedup stark."},
{t:"thr", q:"Amdahls Gesetz: f = 0,5 parallelisierbar, N = 2 Prozessoren. Speedup?", o:["≈ 1,33","2","1,5","1,25"], a:0, e:"1 / (0,5 + 0,5/2) = 1 / 0,75 ≈ 1,33."},
{t:"thr", q:"Warum gelten Threads als „leichtgewichtig“ im Vergleich zu Prozessen?", o:["Sie teilen Adressraum und Ressourcen; nur PC, Register und Stack sind eigen","Sie laufen immer im Kernel Mode und sparen dadurch Moduswechsel","Sie haben keinen eigenen Stack und brauchen daher kaum Speicher","Sie werden vom Scheduler immer mit niedrigerer Priorität behandelt"], a:0, e:"Erzeugen, Beenden und Umschalten von Threads ist billiger, weil kein neuer Adressraum und keine neuen Ressourcen angelegt werden. Beispiele: MS-DOS = ein Prozess/ein Thread, JRE = ein Prozess/mehrere Threads."},
{t:"thr", q:"Wie arbeitet ein multi-threaded Web-Server nach dem Dispatcher/Worker-Prinzip?", o:["Ein Dispatcher-Thread verteilt Anfragen an Worker-Threads","Jeder Worker-Thread nimmt selbst Anfragen aus dem Netz an","Ein Worker-Thread verteilt Anfragen an mehrere Dispatcher","Für jede Anfrage startet der Dispatcher einen neuen Prozess"], a:0, e:"Dispatcher Thread liest Anfragen aus dem Netz und übergibt sie an Worker Threads, die u. a. den Web Page Cache nutzen."},
{t:"thr", q:"Was ist ein Thread?", o:["Eine Ausführungseinheit innerhalb eines Prozesses","Ein eigenständiges Programm mit eigenem Adressraum","Ein Speicherbereich, den mehrere Prozesse teilen","Ein Auftrag, der im Batch-Betrieb abgearbeitet wird"], a:0, e:"Der Prozess ist die Einheit für Ressourcenbesitz (Adressraum, Dateien), der Thread die Einheit für Ausführung und Scheduling (PC, Register, Stack, Zustand). Ein Prozess kann mehrere Threads haben."},
{t:"thr", q:"Was ist der Unterschied zwischen Nebenläufigkeit (Concurrency) und Parallelität?", o:["Nebenläufig: abwechselnd verzahnt; parallel: wirklich gleichzeitig","Nebenläufig: wirklich gleichzeitig; parallel: abwechselnd verzahnt","Nebenläufig: nur bei Prozessen; parallel: nur bei Threads","Kein Unterschied, beide Begriffe meinen genau dasselbe"], a:0, e:"Auf einem Kern laufen Threads nur nebenläufig (Zeitscheiben, Interleaving). Erst mit mehreren Kernen laufen sie echt parallel. Beides kann zu Race Conditions führen."},
{t:"thr", q:"Was ist Grand Central Dispatch (GCD) unter macOS?", o:["Ein Thread-Pool, an den die App „Blocks“ über FIFO-Queues gibt","Ein Thread-Pool, an den die App Prozesse über LIFO-Stacks gibt","Ein Scheduler, der jedem Block einen eigenen Kernel-Thread erzeugt","Ein Scheduler, der Blocks strikt nacheinander auf einem Core ausführt"], a:0, e:"GCD stellt einen Pool von Threads bereit; Programmierer definieren Blocks (in sich geschlossene Arbeitseinheiten), die per FIFO-Queues gescheduled und nebenläufig ausgeführt werden."},
{t:"thr", q:"Was passiert mit den Threads, wenn ein Prozess beendet oder suspendiert wird?", o:["Alle Threads werden ebenfalls beendet bzw. suspendiert","Nur der Haupt-Thread wird beendet bzw. suspendiert","Die Threads laufen weiter, bis sie selbst terminieren","Die Threads werden an den Elternprozess übergeben"], a:0, e:"Wird ein Prozess beendet bzw. suspendiert, werden auch alle seine Threads beendet bzw. suspendiert."},
{t:"thr", q:"Was unterscheidet User-Level Threads (ULT) grundsätzlich von Kernel-Level Threads (KLT)?", o:["Bei ULT verwaltet eine Bibliothek die Threads, der Kernel kennt sie nicht","Bei ULT verwaltet der Kernel die Threads, die Anwendung kennt sie nicht","ULT laufen nur im User Mode, KLT laufen ausschließlich im Kernel Mode","ULT gehören zu einem Prozess, KLT zu mehreren Prozessen gleichzeitig"], a:0, e:"ULT: Thread-Verwaltung komplett im User Space (schneller Wechsel, aber ein blockierender Syscall blockiert alle). KLT: Der Kernel kennt und scheduled jeden Thread (echte Parallelität, aber Mode Switch)."},

// ---------- Scheduling Basics ----------
{t:"sch1", q:"Welcher Scheduler entscheidet, welche Programme als Prozesse zugelassen werden (Grad der Multiprogrammierung)?", o:["Long-Term Scheduler","Short-Term Scheduler","Medium-Term Scheduler","I/O Scheduler"], a:0, e:"Long-term: Auswahl/Zulassung neuer Prozesse. Medium-term: Swapping (im Speicher halten). Short-term: Ausführung (Dispatcher)."},
{t:"sch1", q:"Welcher Scheduler wird am häufigsten ausgeführt und heißt auch Dispatcher?", o:["Short-Term Scheduler","Long-Term Scheduler","Medium-Term Scheduler","I/O Scheduler"], a:0, e:"Short-term Scheduling: häufigste Ausführung, feinste Entscheidungen, eventgesteuert (Clock Interrupts, I/O Interrupts, Syscalls, Signale)."},
{t:"sch1", q:"Wofür ist der Medium-Term Scheduler zuständig?", o:["Swapping","Zulassung neuer Jobs","Auswahl des nächsten Prozesses","Bearbeitung von I/O-Anfragen"], a:0, e:"Medium-term ist Teil des Swappings: Swapping-in nach Grad der Multiprogrammierung, Swapping-out nach Speicherbedarf."},
{t:"sch1", q:"Welches Kriterium ist systemorientiert (nicht benutzerorientiert)?", o:["Throughput","Response Time","Turnaround Time","Predictability"], a:0, e:"Benutzerorientiert: Turnaround, Response Time, Deadlines, Predictability. Systemorientiert: Throughput, CPU Utilization, Fairness, Priorities, Balancing Resources."},
{t:"sch1", q:"Was ist das wichtigste Ziel bei Echtzeitsystemen?", o:["Deadlines einhalten, Vorhersagbarkeit","Durchsatz maximieren, CPU auslasten","Turnaround Time minimieren","Response Time, Proportionalität"], a:0, e:"Batch: Throughput, Turnaround, CPU Utilization. Interaktiv: Response Time, Proportionality. Realtime: Deadlines einhalten, Predictability."},
{t:"sch1", q:"Was bedeutet „preemptive“ Scheduling?", o:["Das OS kann den laufenden Prozess unterbrechen und nach Ready verschieben","Der laufende Prozess läuft weiter, bis er terminiert oder selbst blockiert","Das OS kann den laufenden Prozess nur bei einem I/O-Aufruf unterbrechen","Der Prozess mit der höchsten Priorität läuft immer ohne Unterbrechung"], a:0, e:"Non-preemptive: läuft bis Terminierung oder Blockade. Preemptive: Unterbrechung z. B. bei Ankunft eines neuen Prozesses, bei Interrupts oder periodisch per Clock Interrupt."},
{t:"sch1", q:"Wie wählt FCFS (First Come First Served) den nächsten Prozess aus?", o:["Den Prozess, der am längsten wartet","Den Prozess mit der kürzesten Bedienzeit","Den Prozess mit der kürzesten Restzeit","Reihum jeden für eine feste Zeitscheibe"], a:0, e:"Selection Function von FCFS: max[w] (längste Zeit im System). Zum Vergleich: SPN min[s], SRT min[s − e], RR constant (Zeitscheibe). FCFS ist non-preemptive."},
{t:"sch1", q:"Warum kann bei SPN Starvation (Verhungern) auftreten?", o:["Kommen ständig kurze Prozesse nach, wird ein langer nie ausgewählt","Ein laufender Prozess wird ständig von neuen Prozessen unterbrochen","Prozesse mit gleicher Länge blockieren sich gegenseitig dauerhaft","Die geschätzte Bedienzeit wird mit der Zeit immer ungenauer"], a:0, e:"Starvation = ein bereiter Prozess bekommt auf unbestimmte Zeit keine CPU. Möglich bei SPN, SRT und Priority Queuing; FCFS und Round Robin sind starvation-frei."},
{t:"sch1", q:"Welches Verfahren benachteiligt kurze und I/O-lastige Prozesse?", o:["FCFS","Round Robin","SPN","SRT"], a:0, e:"FCFS benachteiligt kurze und I/O-lastige Prozesse (bevorzugt CPU-lastige). RR behandelt alle fair. SPN/SRT benachteiligen lange Prozesse."},
{t:"sch1", q:"Was ist SRT (Shortest Remaining Time)?", o:["Die preemptive Variante von SPN","Die non-preemptive Variante von SPN","Die preemptive Variante von FCFS","Round Robin mit variablem Quantum"], a:0, e:"SRT: wählt den Prozess mit der kürzesten erwarteten Restzeit; neuer kurzer Job verdrängt einen laufenden längeren Job (Verdrängung bei Ankunft)."},
{t:"sch1", q:"Prozesse: A (Ankunft 0, Dauer 3), B (2, 6), C (4, 4), D (6, 5), E (8, 2). Turnaround Time von C bei FCFS?", o:["9","4","13","7"], a:0, e:"FCFS: A 0–3, B 3–9, C 9–13, D 13–18, E 18–20. Turnaround C = 13 − 4 = 9."},
{t:"sch1", q:"Gleiche Prozesse (A 0/3, B 2/6, C 4/4, D 6/5, E 8/2). Wann ist E bei SPN fertig?", o:["11","20","10","15"], a:0, e:"A 0–3, B 3–9 (einziger Wartender). Bei t = 9 warten C(4), D(5), E(2) → E 9–11, dann C 11–15, D 15–20."},
{t:"sch1", q:"Was misst die Turnaround Time eines Prozesses?", o:["Die Zeit von der Ankunft bis zur Fertigstellung","Die Zeit von der Ankunft bis zur ersten Reaktion","Die reine Rechenzeit des Prozesses auf der CPU","Die Zeit, die der Prozess in der Ready-Queue wartet"], a:0, e:"Turnaround Time = Fertigstellung − Ankunft = Wartezeit + Bedienzeit. Im Folienbeispiel hat SRT die kleinste mittlere Turnaround Time (7,20), knapp vor SPN (7,60)."},
{t:"sch1", q:"Was passiert, wenn das Time Quantum bei Round Robin länger ist als der längste Prozess?", o:["RR verhält sich wie FCFS","RR verhält sich wie SPN","RR verhält sich wie SRT","Kurze Prozesse verhungern"], a:0, e:"Wird nie unterbrochen, läuft jeder Prozess am Stück in Ankunftsreihenfolge → FCFS. Sinnvoll ist ein Quantum etwas größer als eine typische Interaktion."},
{t:"sch1", q:"Was ist ein Nachteil von Round Robin?", o:["Kein Unterschied zwischen CPU- und I/O-bound Prozessen","Lange Prozesse können verhungern (Starvation)","Kurze Prozesse werden stark benachteiligt","Die Bedienzeit jedes Prozesses muss bekannt sein"], a:0, e:"RR nutzt Clock-basierte Preemption (Time Slicing), ist effektiv für Time-Sharing und hat keine Starvation, behandelt aber CPU- und I/O-lastige Prozesse gleich."},
{t:"sch1", q:"Wie werden Prozesse innerhalb einer Prioritätswarteschlange (Priority Queuing) bedient?", o:["FCFS","LIFO","SPN","Round Robin"], a:0, e:"Zulassung zur Queue nach Priorität, Bedienung der Queues nach Priorität – intern werden die Queues als FCFS behandelt."},
{t:"sch1", q:"Was ist das zentrale Problem bei SPN?", o:["Die Bedienzeit muss geschätzt werden","Es unterbricht laufende Prozesse zu oft","Kurze Prozesse müssen lange warten","Es braucht eine Zeitscheibe pro Prozess"], a:0, e:"„Wie schätzt man die benötigte Zeit jedes Prozesses?“ – SPN braucht eine Schätzung der Bedienzeit. Bei Gleichstand wird FCFS genutzt."},

// ---------- Scheduling Advanced ----------
{t:"sch2", q:"Was beschreibt die Granularität (Grain Size) von Parallelität?", o:["Wie oft parallele Teile sich synchronisieren müssen","Wie viele Prozessoren ein System insgesamt besitzt","Wie groß die Zeitscheibe eines einzelnen Threads ist","Wie viel Speicher ein paralleler Prozess belegt"], a:0, e:"Gemessen am Synchronisationsintervall in Instruktionen: Fine < 20, Medium 20–200 (Parallelität innerhalb einer Anwendung), Coarse 200–2000, Very Coarse 2000–1M (verteilt über Netzknoten). Je feiner, desto häufiger wird synchronisiert."},
{t:"sch2", q:"Was ist ein Nachteil der Master/Slave-Architektur?", o:["Fällt der Master aus, stürzt das ganze System ab","Zwei Prozessoren könnten denselben Prozess wählen","Prozesse können aus der Ready-Queue verloren gehen","Der Kernel muss auf jedem Prozessor laufen können"], a:0, e:"Master/Slave: Kernel-Funktionen laufen auf einem Prozessor; einfache Konfliktlösung, aber Master = Single Point of Failure und möglicher Flaschenhals. Die anderen Nachteile gehören zur Peer-Architektur."},
{t:"sch2", q:"Was kennzeichnet die Peer-Architektur?", o:["Kernel läuft auf jedem Prozessor, jeder scheduled sich selbst","Kernel läuft auf einem Prozessor, der alle anderen scheduled","Jeder Prozess ist fest an einen bestimmten Prozessor gebunden","Prozessoren sind spezialisiert und von einem Master gesteuert"], a:0, e:"Peer: Self-Scheduling aus einem Pool. Nachteile: komplexer, es muss verhindert werden, dass zwei Prozessoren denselben Prozess wählen oder Prozesse verloren gehen."},
{t:"sch2", q:"Was ist Gang Scheduling?", o:["Alle Threads eines Prozesses werden gleichzeitig geschedult","Alle Threads eines Prozesses laufen nacheinander auf einem Core","Threads verschiedener Prozesse teilen sich eine Zeitscheibe","Jeder Thread bekommt dauerhaft einen eigenen Prozessor"], a:0, e:"Gang Scheduling: Threads eines Prozesses laufen gleichzeitig auf mehreren Prozessoren → weniger Synchronisationsblockaden, weniger Prozesswechsel. (Dauerhaft eigener Prozessor = Dedicated Processor Assignment)"},
{t:"sch2", q:"Was ist ein Nachteil von Load Sharing?", o:["Die zentrale Queue braucht Mutual Exclusion","Prozessoren bleiben oft idle, obwohl Arbeit da ist","Die Last wird ungleichmäßig auf CPUs verteilt","Es ist ein zentraler Scheduler-Prozessor nötig"], a:0, e:"Load Sharing: Vorteile – gleichmäßige Last, kein Prozessor idle, kein zentraler Scheduler. Nachteile – zentrale Queue mit Mutual Exclusion, Threads laufen selten wieder auf demselben Prozessor (Cache)."},
{t:"sch2", q:"Warum steigt der Speedup nicht beliebig mit der Anzahl der Threads?", o:["Overhead und Konkurrenz um Cores und Caches wachsen mit","Der Kernel erlaubt pro Prozess höchstens acht Threads","Mehr Threads verlängern die Zeitscheibe jedes Threads","Threads können nie gleichzeitig auf Speicher zugreifen"], a:0, e:"Matrix-Beispiel: 8 Threads → Speedup 6,5, 12 → 5,2, 16 → 3,9, 24 → 2,8. Mit mehr Threads als Cores kommen Kontextwechsel, Synchronisation und Cache-Konflikte hinzu; außerdem begrenzt der serielle Anteil (Amdahl)."},
{t:"sch2", q:"Was ist das Ziel von contention-aware Scheduling?", o:["Threads so auf Cores verteilen, dass der geteilte Cache optimal genutzt wird","Threads so auf Cores verteilen, dass jeder Core gleich viele Threads hat","Threads mit hohem Speicherbedarf immer auf demselben Core bündeln","Threads so verteilen, dass möglichst viele auf den Hauptspeicher zugreifen"], a:0, e:"Threads auf benachbarten Cores konkurrieren um Cache. Ziel: Effektivität des Shared Cache maximieren und Off-Chip-Speicherzugriffe minimieren."},
{t:"sch2", q:"Was unterscheidet Hard von Soft Realtime?", o:["Hard: Verpasste Deadline verursacht Schaden. Soft: Deadline erwünscht, nicht zwingend","Hard: Deadline erwünscht, nicht zwingend. Soft: Verpasste Deadline verursacht Schaden","Hard: Task läuft periodisch. Soft: Task läuft aperiodisch","Hard: Deadline gilt für den Start. Soft: Deadline gilt für das Ende"], a:0, e:"Hard: Verpassen führt zu inakzeptablem Schaden/fatalem Fehler. Soft: Es ergibt trotzdem Sinn, den Task nach der Deadline abzuschließen."},
{t:"sch2", q:"Welche Klasse von Realtime-Scheduling führt KEINE Feasibility-Analyse durch?", o:["Dynamic best effort","Static table-driven","Static priority-driven preemptive","Dynamic planning-based"], a:0, e:"Dynamic best effort: keine Analyse; das System versucht alle Deadlines zu halten und bricht Prozesse ab, deren Deadline verpasst wurde."},
{t:"sch2", q:"Was bedeutet Determinismus bei Echtzeitsystemen?", o:["Operationen laufen zu festen Zeiten oder in festen Zeitintervallen ab","Das System liefert bei gleicher Eingabe immer dieselbe Ausgabe","Das System reagiert möglichst schnell auf jeden Interrupt","Das System läuft bei Teilausfällen eingeschränkt weiter"], a:0, e:"Determinismus: Es ist garantiert, wie lange das OS höchstens braucht, um auf einen Interrupt zu reagieren. Weitere Echtzeit-Eigenschaften: Responsiveness, User Control, Reliability, Fail-soft Operation."},
{t:"sch2", q:"Welches Verfahren hält im Deadline-Beispiel (Tasks A und B) alle Deadlines ein?", o:["Earliest Deadline Scheduling","Fixed Priority, A hat Priorität","Fixed Priority, B hat Priorität","Round Robin"], a:0, e:"Fixed-Priority verpasst Deadlines (A priorisiert: B2 verpasst; B priorisiert: A1 und A4 verpasst). Earliest Deadline First hält alle ein."},
{t:"sch2", q:"Was ist ein „tightly coupled multiprocessor“?", o:["Prozessoren mit gemeinsamem Hauptspeicher, gesteuert von einem OS","Autonome Rechner mit eigenem Speicher, verbunden über ein Netz","Ein Master-Prozessor mit spezialisierten Worker-Prozessoren","Ein Prozessor mit mehreren Hardware-Threads pro Kern"], a:0, e:"Tightly coupled: gemeinsamer Hauptspeicher, Steuerung durch ein OS. Distributed/Cluster: autonome Systeme mit eigenem Speicher. Functionally specialized: Master + spezialisierte Worker."},
{t:"sch2", q:"Warum reichen Prioritäten allein für Echtzeitsysteme nicht aus?", o:["Sie erfassen nicht den Zeitpunkt, zu dem ein Task fertig sein muss","Sie lassen sich während der Laufzeit eines Tasks nicht mehr ändern","Sie führen bei mehreren Echtzeit-Tasks zwangsläufig zu Deadlocks","Sie verursachen beim Kontextwechsel zu viel Verwaltungsaufwand"], a:0, e:"Echtzeitanwendungen geht es nicht um reine Geschwindigkeit, sondern um Fertigstellung zur richtigen Zeit – daher Deadline Scheduling mit Ready Time, Starting/Completion Deadline usw."},

// ---------- Sync & Deadlocks ----------
{t:"sync", q:"Welche vier Bedingungen müssen für einen Deadlock gelten?", o:["Mutual Exclusion, Hold-and-Wait, No Preemption, Circular Wait","Mutual Exclusion, Hold-and-Wait, Preemption, Circular Wait","Mutual Exclusion, Starvation, No Preemption, Circular Wait","Race Condition, Hold-and-Wait, No Preemption, Circular Wait"], a:0, e:"Alle vier: nur ein Prozess pro Ressource; Halten und Warten; keine erzwungene Wegnahme; geschlossene Kette von Prozessen (Circular Wait)."},
{t:"sync", q:"Welche Deadlock-Strategie gewährt eine Anfrage nicht, wenn sie zu einem Deadlock führen könnte?", o:["Deadlock Avoidance","Deadlock Prevention","Deadlock Detection","Deadlock Recovery"], a:0, e:"Prevention: Bedingungen ausschließen (z. B. Circular Wait verhindern). Detection: Anfragen gewähren, periodisch prüfen, dann recovern. Avoidance: riskante Zuteilungen nicht gewähren."},
{t:"sync", q:"Was ist die schnellste Form der Interprozesskommunikation?", o:["Shared Memory","Pipes","Messages","Signals"], a:0, e:"Shared Memory: gemeinsamer Block virtuellen Speichers. Mutual Exclusion ist dabei nicht eingebaut – die Prozesse müssen selbst dafür sorgen."},
{t:"sync", q:"Was sind Pipes?", o:["FIFO-Ringpuffer für Producer-Consumer zwischen zwei Prozessen","LIFO-Stapel für Producer-Consumer zwischen zwei Prozessen","Gemeinsame Speicherbereiche mit eingebauter Mutual Exclusion","Nachrichten mit Typ, die in einer Mailbox abgelegt werden"], a:0, e:"Pipes: Circular Buffers, FIFO; von Prozess A geschrieben, von B gelesen. Zwei Arten: named und unnamed."},
{t:"sync", q:"Was ist Message Passing?", o:["Prozesse tauschen Daten über send/receive-Nachrichten aus","Prozesse lesen und schreiben einen gemeinsamen Speicherbereich","Prozesse melden sich gegenseitig nur asynchrone Ereignisse","Prozesse sperren eine Ressource über einen gemeinsamen Zähler"], a:0, e:"Message = Block von Bytes mit Typ. Unter UNIX: msgsnd und msgrcv; jedem Prozess ist eine Message Queue zugeordnet, die wie ein Briefkasten funktioniert. Der Kernel übernimmt Übertragung und Synchronisation."},
{t:"sync", q:"Was entspricht einer binären Semaphore?", o:["Mutex Lock","Pipe","Signal","Shared Memory"], a:0, e:"Binary Semaphore ⇒ MUTEX LOCK. Semaphoren-Infos: aktueller Wert, PID des letzten Prozesses, Anzahl Wartender."},
{t:"sync", q:"Wie kann ein Prozess auf ein Signal reagieren?", o:["Default-Aktion, Signal-Handler ausführen oder ignorieren","Default-Aktion, Signal weiterleiten oder blockieren","Signal-Handler ausführen, Prozess forken oder beenden","Nur Default-Aktion oder Signal-Handler, ignorieren geht nicht"], a:0, e:"Signal = Software-Mechanismus für asynchrone Ereignisse, ähnlich einem Hardware-Interrupt; geliefert über ein Feld in der Prozesstabelle."},
{t:"sync", q:"Was ist eine Race Condition?", o:["Das Ergebnis hängt von der Ausführungsreihenfolge ab","Prozesse warten zyklisch aufeinander und blockieren dauerhaft","Ein Prozess bekommt wegen niedriger Priorität nie CPU-Zeit","Ein Thread wartet aktiv in einer Schleife auf einen Lock"], a:0, e:"Mehrere Prozesse lesen/schreiben Daten; der „Verlierer“ schreibt zuletzt und bestimmt den Endwert. (Zyklisches Warten = Deadlock, nie CPU = Starvation, aktives Warten = Spinlock)"},
{t:"sync", q:"Warum ist i++ in Java nicht atomar?", o:["Es besteht aus mehreren Bytecode-Instruktionen","Die JVM führt es immer im Kernel Mode aus","Static-Variablen liegen auf dem Stack jedes Threads","Der Garbage Collector kann es jederzeit abbrechen"], a:0, e:"getstatic, iconst_1, iadd, putstatic – zwischen Lesen und Schreiben kann ein Kontextwechsel passieren, ein anderer Thread liest denselben alten Wert → Update geht verloren."},
{t:"sync", q:"Wann ist ein Spinlock sinnvoll?", o:["Wenn die erwartete Wartezeit sehr kurz ist","Wenn die erwartete Wartezeit sehr lang ist","Wenn viele Threads lange um den Lock konkurrieren","Wenn der wartende Thread schlafen gelegt werden soll"], a:0, e:"Spinlock = aktives Warten (busy waiting): while (lock == 1); Nachteil: ausgesperrte Threads verbrauchen weiter CPU-Zeit."},
{t:"sync", q:"Welche Regel gilt für einen Mutex?", o:["Nur der sperrende Thread darf ihn entsperren","Jeder Thread des Prozesses darf ihn entsperren","Er erlaubt bis zu N Threads gleichzeitig","Er wird nach Ablauf der Zeitscheibe freigegeben"], a:0, e:"Mutex: nur ein Thread gleichzeitig im kritischen Bereich; Sperren mit mutex_enter, Standard-Blocking-Policy ist ein Spinlock, interruptbasiertes Blockieren optional."},
{t:"sync", q:"Was zeichnet atomare Operationen aus?", o:["Ausführung ohne Unterbrechung und ohne Störung","Ausführung ohne Unterbrechung, aber nur im User Mode","Ausführung mit Mutex-Schutz durch den Kernel","Ausführung in genau einem Taktzyklus"], a:0, e:"Einfachster Ansatz der Kernel-Synchronisation. Arten: Integer Operations (z. B. Zähler) und Bitmap Operations."},
{t:"sync", q:"Was ist ein Deadlock?", o:["Prozesse blockieren dauerhaft, weil jeder auf ein Ereignis eines anderen wartet","Prozesse liefern falsche Ergebnisse, weil sie gleichzeitig Daten schreiben","Ein Prozess wird dauerhaft übergangen, weil andere höhere Priorität haben","Ein Prozess wartet aktiv in einer Schleife, bis eine Variable frei wird"], a:0, e:"Permanent, weil keines der Ereignisse je ausgelöst wird. Für den allgemeinen Fall gibt es keine effiziente Lösung."},

// ---------- Memory ----------
{t:"mem", q:"Was ist interne Fragmentierung?", o:["Ungenutzter Platz innerhalb eines zugeteilten Blocks","Ungenutzte Lücken zwischen zugeteilten Blöcken","Verstreute Ablage einer Datei auf der Festplatte","Aufteilung eines Prozesses in Seiten fester Größe"], a:0, e:"Bekommt ein Prozess einen festen Block (Fixed Partitioning, Buddy-Block, letzte Seite beim Paging), der größer ist als nötig, bleibt der Rest im Block ungenutzt. Externe Fragmentierung sind dagegen Lücken zwischen Blöcken (Dynamic Partitioning)."},
{t:"mem", q:"Was macht die MMU?", o:["Übersetzt virtuelle in physische Adressen","Übersetzt physische in virtuelle Adressen","Lagert Seiten auf die Festplatte aus","Verwaltet die Zuteilung von Cache-Zeilen"], a:0, e:"Die CPU sendet virtuelle Adressen an die MMU, die MMU sendet physische Adressen an den Speicher."},
{t:"mem", q:"Welche Adresse gibt eine Position relativ zu einem bekannten Punkt an?", o:["Relative Adresse","Physische Adresse","Absolute Adresse","Reale Adresse"], a:0, e:"Logical: unabhängig von der aktuellen Speicherzuordnung. Relative: Sonderfall logisch, relativ zu einem bekannten Punkt. Physical/Absolute: tatsächliche Position im RAM."},
{t:"mem", q:"Seitengröße 4 KB. Welcher Adressbereich gehört zur virtuellen Seite 8K–12K?", o:["8192–12287","8000–12000","8192–12288","8191–12287"], a:0, e:"Jede Seite beginnt bei einem Vielfachen von 4096 und endet 4095 Adressen höher: 2·4096 = 8192 bis 8192 + 4095 = 12287."},
{t:"mem", q:"Virtuelle Seite 2 (8K–12K) ist auf Page Frame 6 abgebildet, Seitengröße 4096. Physische Adresse zu virtueller Adresse 8200?", o:["24584","8200","24576","32776"], a:0, e:"Offset = 8200 − 8192 = 8. Physisch = 6 · 4096 + 8 = 24576 + 8 = 24584."},
{t:"mem", q:"Welche Art der Fragmentierung entsteht bei Dynamic Partitioning?", o:["Externe Fragmentierung","Interne Fragmentierung","Interne und externe","Keine Fragmentierung"], a:0, e:"Prozesse bekommen genau so viel wie nötig, aber zwischen ihnen entstehen Lücken (extern). Gegenmittel: Compaction – zeitaufwendig und kostet CPU-Zeit."},
{t:"mem", q:"Welche Placement-Strategie wählt den Block, der der Anfrage größenmäßig am nächsten kommt?", o:["Best-fit","First-fit","Next-fit","Worst-fit"], a:0, e:"Best-fit: passendste Größe. First-fit: erster ausreichender Block vom Anfang. Next-fit: ab der letzten Platzierung der nächste ausreichende Block."},
{t:"mem", q:"Buddy System mit 1 MB: Eine Anfrage über 100 KB bekommt welchen Block?", o:["128 KB","100 KB","256 KB","64 KB"], a:0, e:"Blöcke haben Größe 2^K. Die kleinste Zweierpotenz ≥ 100 KB ist 128 KB (1M → 512K → 256K → 128K)."},
{t:"mem", q:"Buddy System: Welche Blockgröße bekommt eine Anfrage über 240 KB?", o:["256 KB","240 KB","512 KB","128 KB"], a:0, e:"Kleinste Zweierpotenz ≥ 240 KB ist 256 KB (Beispiel: B = 256K)."},
{t:"mem", q:"Was gilt für Segmentation im Vergleich zu Paging?", o:["Variable Länge, für Programmierer sichtbar, keine interne Fragmentierung","Feste Länge, für Programmierer unsichtbar, keine externe Fragmentierung","Variable Länge, für Programmierer unsichtbar, keine externe Fragmentierung","Feste Länge, für Programmierer sichtbar, keine interne Fragmentierung"], a:0, e:"Segmentation: variable Länge mit Maximalgröße, Adresse = Segmentnummer + Offset, ähnlich Dynamic Partitioning, eliminiert interne Fragmentierung, meist sichtbar."},
{t:"mem", q:"Warum kann Prozess D im Paging-Beispiel geladen werden, obwohl keine zusammenhängenden Frames frei sind?", o:["Die Page Table kann Seiten auf beliebige, verstreute Frames abbilden","Das OS führt vorher eine Compaction durch und schiebt C nach oben","D wird in Segmente variabler Länge zerlegt, die in die Lücken passen","Die freien Frames werden per Buddy System zu einem Block vereinigt"], a:0, e:"Nach dem Auslagern von B nutzt D die Frames 4–6 sowie 11–12. Die Page Table pro Prozess enthält den Frame jeder Seite."},
{t:"mem", q:"Wie funktioniert der Second-Chance-Algorithmus?", o:["Älteste Seite mit gesetztem R-Bit: Bit löschen, Seite ans Ende der Liste","Älteste Seite mit gesetztem R-Bit: Seite sofort verdrängen","Neueste Seite mit gesetztem R-Bit: Bit löschen, Seite an den Anfang","Älteste Seite ohne R-Bit: Bit setzen, Seite ans Ende der Liste"], a:0, e:"FIFO-Liste: Seite A (Ladezeit 0) hat R-Bit gesetzt → bekommt eine zweite Chance und wird wie neu geladen (Zeit 20) ans Ende gehängt."},
{t:"mem", q:"Warum nutzt man mehrstufige Page Tables (z. B. Linux: Page Directory → Middle Directory → Page Table)?", o:["Damit nicht die ganze riesige Tabelle im RAM liegen muss","Damit Adressübersetzungen weniger Speicherzugriffe brauchen","Damit jeder Prozess mehr physischen Speicher bekommt","Damit Seiten unterschiedlicher Größe möglich werden"], a:0, e:"Eine einstufige Tabelle für einen großen Adressraum wäre riesig, obwohl die meisten Einträge leer sind. Mehrstufig müssen nur die benutzten Teile existieren – das Page Directory muss für einen aktiven Prozess im RAM sein."},
{t:"mem", q:"Was ist ein Page Fault?", o:["Zugriff auf eine Seite, die gerade nicht im RAM liegt","Zugriff auf eine Adresse außerhalb des eigenen Adressraums","Eine beschädigte Seite, die beim Lesen von der Platte entsteht","Ein voller Seitenrahmen, in den keine Daten mehr passen"], a:0, e:"Die MMU löst einen Interrupt aus, das OS blockiert den Prozess, lädt die Seite nach (ggf. nach Verdrängung einer anderen, z. B. per Clock-Algorithmus) und setzt ihn fort. Ein Page Fault ist normal, kein Programmfehler."},
{t:"mem", q:"Was ist ein virtueller Adressraum?", o:["Ein eigener, logischer Adressbereich pro Prozess, den die MMU auf RAM abbildet","Der Teil des Hauptspeichers, der für das Betriebssystem reserviert ist","Der Bereich auf der Festplatte, in den Seiten ausgelagert werden","Ein gemeinsamer Adressbereich, den alle Prozesse zusammen nutzen"], a:0, e:"Jeder Prozess sieht seine eigenen Adressen ab 0, unabhängig davon, wo die Daten physisch liegen. Beispiel Windows 32-Bit: 4 GB virtuell pro Prozess, davon standardmäßig ca. 2 GB User Space."},
{t:"mem", q:"Was ist Thrashing?", o:["Das System lagert ständig Seiten aus und ein und kommt kaum zum Rechnen","Ein Prozess überschreibt versehentlich die Seiten eines anderen Prozesses","Das System gibt nicht mehr benötigte Seiten im Hauptspeicher frei","Der Cache wird bei jedem Kontextwechsel vollständig geleert"], a:0, e:"Passiert, wenn zu viele Prozesse für zu wenig RAM aktiv sind: Fast jeder Zugriff erzeugt einen Page Fault, die CPU wartet nur noch auf die Platte. Gegenmittel: weniger Prozesse (Medium-Term Scheduler) oder größeres Resident Set."},
{t:"mem", q:"Was ist das Resident Set eines Prozesses?", o:["Der Teil des Prozesses, der im RAM liegt","Der Teil des Prozesses, der im Swap liegt","Die Seiten, die als Nächstes geladen werden","Die Seiten, die mit anderen Prozessen geteilt sind"], a:0, e:"Wird eine Adresse gebraucht, die nicht im RAM liegt, wird ein Interrupt erzeugt (Page Fault), der Prozess blockiert und das Stück nachgeladen."},
{t:"mem", q:"Welcher Vorteil von virtuellem Speicher wird genannt?", o:["Ein Prozess kann größer sein als der gesamte Hauptspeicher","Jeder Speicherzugriff wird schneller als ohne virtuellen Speicher","Page Faults können nicht mehr auftreten","Prozesse müssen immer komplett im RAM liegen"], a:0, e:"Zudem passen mehr Prozesse in den RAM, da nur Teile geladen sind → bessere Prozessorauslastung. Overlays sind nicht mehr Aufgabe des Programmierers."},
{t:"mem", q:"Welches Problem löst Relocation?", o:["Ein Prozess kann nach Swapping an anderer Stelle im RAM landen","Ein Prozess darf nicht auf fremde Speicherbereiche zugreifen","Mehrere Prozesse sollen eine Bibliothek gemeinsam nutzen","Programme bestehen aus unabhängig kompilierten Modulen"], a:0, e:"Programmierer wissen nicht, wo ihr Programm im Speicher liegt; nach Swapping oder Compaction kann es woanders liegen. (Die anderen Optionen beschreiben Protection, Sharing und Logical Organization.)"},

// ---------- File Systems ----------
{t:"fs", q:"Wie lautet die Hierarchie von Datenelementen (klein → groß)?", o:["Field → Record → File → Database","Record → Field → File → Database","Field → File → Record → Database","Field → Record → Database → File"], a:0, e:"Field: einzelner Wert. Record: zusammengehörige Fields. File: Sammlung gleichartiger Records. Database: zusammenhängende Daten mit expliziten Beziehungen."},
{t:"fs", q:"Bei welcher Dateiorganisation werden Daten in Ankunftsreihenfolge gesammelt und per erschöpfender Suche gefunden?", o:["Pile","Sequential File","Indexed File","Hashed File"], a:0, e:"Pile: einfachste Organisation, variable Records, chronologische Reihenfolge, Zugriff via Exhaustive Search."},
{t:"fs", q:"Welche Dateiorganisation lässt sich als einzige leicht auf Band UND Platte speichern?", o:["Sequential File","Indexed File","Hashed File","Indexed Sequential File"], a:0, e:"Sequential File: häufigste Struktur, feste Record-Formate, Key-Field, typisch für Batch-Anwendungen."},
{t:"fs", q:"Was fügt das Indexed Sequential File zur sequentiellen Datei hinzu?", o:["Index und Overflow-Datei","Hash-Funktion und Overflow-Datei","Index und variable Felder","Partial Index und Hash-Tabelle"], a:0, e:"Index für Random Access + Overflow File; mehrere Index-Ebenen sind möglich, reduziert die Zugriffszeit stark."},
{t:"fs", q:"Wofür eignet sich ein Indexed File besonders?", o:["Flugbuchungs- und Lagerverwaltungssysteme","Batch-Verarbeitung von Lohnabrechnungen","Archivierung großer Datenmengen auf Band","Protokolldateien in Ankunftsreihenfolge"], a:0, e:"Indexed File: Zugriff nur über Indizes (exhaustive oder partial), variable Record-Länge, eingesetzt wo Aktualität kritisch ist."},
{t:"fs", q:"Was speichert ein UNIX-i-node NICHT?", o:["Den Dateinamen","Die Zugriffsrechte","Die Dateigröße","Die Blockadressen"], a:0, e:"Der i-node enthält alle Infos über eine Datei außer ihrem Namen und dem eigentlichen Inhalt. Der Name steht im Verzeichniseintrag – mehrere Namen können auf denselben i-node zeigen."},
{t:"fs", q:"Welche Indirektionsstufen hat ein UNIX-i-node für große Dateien?", o:["Single, Double, Triple Indirect","Single und Double Indirect","Nur Single Indirect","Single bis Quadruple Indirect"], a:0, e:"Direkte Blockadressen + Single, Double und Triple Indirect Blocks für sehr große Dateien."},
{t:"fs", q:"Lookup von /usr/ast/mbox: In welchem i-node liegt mbox?", o:["60","6","26","406"], a:0, e:"Root: usr → i-node 6 → Block 132: ast → i-node 26 → Block 406: mbox → i-node 60."},
{t:"fs", q:"Was bedeutet chmod 755?", o:["rwxr-xr-x","rwxrwxr-x","rwxr--r--","rw-r-xr-x"], a:0, e:"Jede Ziffer = 3 Bits (r=4, w=2, x=1). 7 = 111 = rwx (Owner), 5 = 101 = r-x (Group), 5 = r-x (Others)."},
{t:"fs", q:"Welche Oktalzahl entspricht rw-r--r--?", o:["644","755","664","640"], a:0, e:"rw- = 110 = 6, r-- = 100 = 4, r-- = 4 → 644."},
{t:"fs", q:"Was unterscheidet einen Hard Link von einem symbolischen Link?", o:["Hard Link zeigt auf den i-node, Symlink auf einen Pfadnamen","Hard Link zeigt auf einen Pfadnamen, Symlink auf den i-node","Hard Link kopiert die Datei, Symlink verweist nur auf sie","Hard Link gilt nur für Verzeichnisse, Symlink nur für Dateien"], a:0, e:"Hard Link: zusätzlicher Verzeichniseintrag für denselben i-node (Link Count steigt). Symbolischer Link: eigene kleine Datei mit dem Pfad des Ziels – wird das Ziel gelöscht, zeigt er ins Leere."},
{t:"fs", q:"Was markiert das Datei-Attribut „Archive (A)“?", o:["Seit dem letzten Backup geändert","Wird automatisch komprimiert","Liegt auf einem Remote-Speicher","Darf nicht verändert werden"], a:0, e:"Backup-Software nutzt das Archive-Bit, um zu entscheiden, welche Dateien gesichert werden müssen. (Compressed, Offline, Read-only sind eigene Attribute.)"},
{t:"fs", q:"Was ist der Unterschied zwischen absolutem und relativem Pfadnamen?", o:["Absolut beginnt beim Root-Verzeichnis, relativ beim Arbeitsverzeichnis","Absolut beginnt beim Arbeitsverzeichnis, relativ beim Root-Verzeichnis","Absolut enthält das Laufwerk, relativ nur den reinen Dateinamen","Absolut zeigt auf einen i-node, relativ auf einen Datenblock"], a:0, e:"Beispiel: /usr/ast/mbox ist absolut (beginnt mit /). Steht man in /usr/ast, reicht der relative Pfad mbox. „.“ ist das aktuelle, „..“ das übergeordnete Verzeichnis."},
{t:"fs", q:"Was ist ein Journaling-Dateisystem (z. B. ext4, NTFS)?", o:["Es protokolliert Änderungen vorab, um nach Abstürzen konsistent zu bleiben","Es speichert von jeder Datei automatisch alle früheren Versionen","Es protokolliert alle Zugriffe der Benutzer für spätere Prüfungen","Es schreibt jede Datei zur Sicherheit doppelt auf die Platte"], a:0, e:"Vor der eigentlichen Änderung wird ein Eintrag ins Journal (Log) geschrieben. Nach einem Absturz wird das Journal abgearbeitet, statt die ganze Platte zu prüfen. exFAT (für Flash, ohne 4-GB-Grenze von FAT32) hat kein Journaling."},
{t:"fs", q:"Welches Zugriffsrecht erlaubt, Daten hinzuzufügen, aber nichts zu ändern oder zu löschen?", o:["Appending","Updating","Reading","Execution"], a:0, e:"Stufen: None, Knowledge, Execution, Reading, Appending, Updating, Changing Protection, Deletion."},
{t:"fs", q:"Was erlaubt das Zugriffsrecht „Knowledge“?", o:["Existenz und Besitzer der Datei erfahren","Inhalt der Datei lesen, aber nicht kopieren","Programm ausführen, aber nicht kopieren","Verzeichnis auflisten, aber nicht betreten"], a:0, e:"Mit Knowledge kann man den Besitzer um weitere Rechte bitten, aber nicht lesen. Ausführen ohne Kopieren = Execution."},
{t:"fs", q:"Was ist das Virtual File System (VFS)?", o:["Einheitliche Schnittstelle über mehreren konkreten Dateisystemen","Ein Dateisystem, das vollständig im Arbeitsspeicher gehalten wird","Ein Dateisystem, das alle Daten über das Netzwerk auf Server spiegelt","Eine Schicht, die Dateien beim Schreiben transparent verschlüsselt"], a:0, e:"Benutzerprozesse rufen POSIX-Funktionen auf; das VFS leitet über V-nodes und Function Pointers an das konkrete FS (FS 1, FS 2 …) weiter."},
{t:"fs", q:"Gemeinsame Datei (Hard Link): Owner C löscht die Datei, B hat einen Link. Was gilt danach?", o:["Datei existiert weiter, Count = 1, Owner bleibt C","Datei existiert weiter, Count = 1, Owner wird B","Datei ist gelöscht, B hat einen ungültigen Link","Datei existiert weiter, Count = 2, Owner bleibt C"], a:0, e:"Vor dem Link Count = 1, nach dem Link Count = 2, nach dem Löschen durch C Count = 1 – der i-node gehört formal noch C."},
{t:"fs", q:"Was speichert eine Partitionstabelle (MBR oder GPT)?", o:["Wo auf der Platte welche Partition beginnt und endet","Welche Blöcke auf der Platte zu welcher Datei gehören","Welche Benutzer welche Rechte auf der Platte haben","Welche Programme beim Systemstart geladen werden"], a:0, e:"Die Partitionstabelle teilt die Platte in Bereiche, die je ein eigenes Dateisystem enthalten können. GPT/UEFI: Block 0 für den Legacy-MBR, dann GPT-Header und Tabelle, am Ende der Platte eine Backup-Kopie."},
{t:"fs", q:"Was ist die unterste Schicht der Dateisystem-Softwarearchitektur?", o:["Device Driver","Basic File System","Basic I/O Supervisor","Logical I/O"], a:0, e:"Von unten: Device Driver → Basic File System (Physical I/O) → Basic I/O Supervisor → Logical I/O → Access Method (Pile, Sequential …) → User Program."},
{t:"fs", q:"Welche Eigenschaft hat das Basic File System (Physical I/O)?", o:["Arbeitet mit Blöcken, kennt aber weder Inhalt noch Dateistruktur","Arbeitet mit Records und kennt die Struktur der Dateien","Startet und beendet alle Datei-I/O und wählt das Gerät aus","Kommuniziert direkt mit den Registern des Peripheriegeräts"], a:0, e:"Basic File System: Blöcke zwischen Platte/Band und RAM, Platzierung und Pufferung. Records = Logical I/O, I/O-Start/Gerätewahl = Basic I/O Supervisor, Register = Device Driver."},
{t:"fs", q:"Warum wird /system unter Android read-only gemountet?", o:["Damit Systemdateien nicht verändert werden können","Damit Apps dort schneller Daten ablegen können","Weil die Partition auf der SD-Karte liegt","Weil /system bei jedem Boot neu erzeugt wird"], a:0, e:"/system ist ro; /data, /cache und /mnt/sdcard sind rw. So bleiben System-Binaries und Bibliotheken geschützt."},
{t:"fs", q:"Was ist ein Nachteil der zusammenhängenden (contiguous) Belegung von Plattenblöcken?", o:["Gelöschte Dateien hinterlassen Lücken","Sequentielles Lesen ist sehr langsam","Jeder Block braucht einen Folgezeiger","Die FAT muss komplett im RAM liegen"], a:0, e:"Beispiel: Nach dem Löschen von D und F bleiben 5 bzw. 6 freie Blöcke als Lücken. Folgezeiger = Linked List, FAT im RAM = File Allocation Table."},
{t:"fs", q:"Was unterscheidet Soft- und Hard-Limit bei Disk Quotas?", o:["Soft-Limit darf mit Warnungen überschritten werden, Hard-Limit nie","Hard-Limit darf mit Warnungen überschritten werden, Soft-Limit nie","Soft-Limit gilt pro Datei, Hard-Limit pro Benutzer","Soft-Limit gilt für Blöcke, Hard-Limit nur für Dateien"], a:0, e:"Quotas werden pro Benutzer in einer Quota-Tabelle geführt: Soft/Hard Block Limit, Soft/Hard File Limit und verbleibende Warnungen."},

// ---------- I/O & RAID ----------
{t:"io", q:"Wie lautet die Schichtung der I/O-Software (oben → unten)?", o:["User-level I/O → Geräteunabh. Software → Treiber → Interrupt Handler → Hardware","User-level I/O → Treiber → Geräteunabh. Software → Interrupt Handler → Hardware","User-level I/O → Geräteunabh. Software → Interrupt Handler → Treiber → Hardware","Geräteunabh. Software → User-level I/O → Treiber → Interrupt Handler → Hardware"], a:0, e:"Interrupt Handler wecken den Treiber nach Abschluss; Device Driver setzen Register und prüfen Status; geräteunabhängige Software übernimmt Naming, Protection, Blocking, Buffering, Allocation."},
{t:"io", q:"Welche I/O-Technik lässt den Prozessor aktiv auf das Ende der Operation warten (busy waiting)?", o:["Programmed I/O","Interrupt-driven I/O","DMA","Asynchronous I/O"], a:0, e:"Programmed I/O: busy wait. Interrupt-driven: CPU arbeitet weiter, Interrupt meldet Ende. DMA: DMA-Modul überträgt Daten direkt zwischen RAM und I/O-Modul."},
{t:"io", q:"Was macht DMA (Direct Memory Access)?", o:["Ein DMA-Modul überträgt Daten zwischen RAM und I/O-Modul","Die CPU überträgt Daten direkt zwischen Cache und I/O-Modul","Ein DMA-Modul lagert Speicherseiten auf die Platte aus","Die CPU fragt das I/O-Modul in einer Schleife nach Daten ab"], a:0, e:"Die CPU wird entlastet, weil sie nicht jedes Wort selbst übertragen muss."},
{t:"io", q:"Was ist ein Gerätetreiber (Device Driver)?", o:["Gerätespezifischer Code, der dem OS ein Gerät nutzbar macht","Ein Hardwarebaustein, der Daten ohne CPU in den RAM kopiert","Eine Anwendung, mit der Nutzer ein Gerät selbst konfigurieren","Die geräteunabhängige Softwareschicht über allen Geräten"], a:0, e:"Der Treiber kennt Register und Eigenheiten genau eines Gerätetyps: Er schreibt Befehle in Geräteregister, prüft den Status und wird nach Abschluss vom Interrupt Handler geweckt."},
{t:"io", q:"Was ist ein blockorientiertes Gerät?", o:["Speichert Daten in Blöcken, adressierbar per Blocknummer","Überträgt einen Bytestrom ohne jede Blockstruktur","Kommuniziert ausschließlich mit entfernten Geräten","Liest jedes Zeichen genau einmal aus einer Queue"], a:0, e:"Blockorientiert: z. B. Platten, USB-Sticks. Stream-orientiert: Bytestrom ohne Blockstruktur – Terminals, Drucker, Kommunikationsports, Maus."},
{t:"io", q:"Was bedeutet das I/O-Designziel „Generality“?", o:["Alle Geräte möglichst einheitlich behandeln","I/O-Operationen möglichst schnell erledigen","Jedem Gerät eine eigene Schnittstelle geben","Geräte nur über allgemeine Treiber ansprechen"], a:0, e:"Die zwei I/O-Designziele: Efficiency (I/O ist oft der Flaschenhals) und Generality (einheitliche Behandlung, hierarchischer, modularer Aufbau – z. B. read/write für alle Geräte)."},
{t:"io", q:"Was ist bei synchronem I/O unter Windows der Fall?", o:["Die Anwendung blockiert bis zum Abschluss","Die Anwendung arbeitet währenddessen weiter","Das OS bündelt mehrere Anfragen zu einer","Die Anfrage wird per DMA im Hintergrund erledigt"], a:0, e:"Asynchron: Anwendung startet die Operation und arbeitet weiter (wird wo möglich zur Performance-Optimierung verwendet). Synchron: blockiert bis Abschluss."},
{t:"io", q:"Welche Eigenschaft haben Character Queues?", o:["Jedes Zeichen kann nur einmal gelesen werden","Jedes Zeichen kann beliebig oft gelesen werden","Zeichen werden in LIFO-Reihenfolge gelesen","Zeichen werden blockweise per DMA gelesen"], a:0, e:"Character Queues: für zeichenorientierte Geräte (Terminals, Drucker), Producer/Consumer-Modell; jedes gelesene Zeichen ist danach „zerstört“."},
{t:"io", q:"Welcher RAID-Level bietet keine Redundanz, sondern nur Striping?", o:["RAID 0","RAID 1","RAID 4","RAID 5"], a:0, e:"RAID 0 ist kein „echtes“ RAID: Daten werden in Strips über alle Platten verteilt, ohne Redundanz."},
{t:"io", q:"Was ist der Hauptnachteil von RAID 1?", o:["Die hohen Kosten","Der hohe Write Penalty","Keine Ausfallsicherheit","Langsames Lesen"], a:0, e:"RAID 1: Spiegelung, kein Write Penalty, bei Ausfall Zugriff über die zweite Platte – aber doppelter Speicherbedarf."},
{t:"io", q:"Wozu dient Parität bei RAID?", o:["Aus ihr lassen sich die Daten einer ausgefallenen Platte rekonstruieren","Sie verteilt die Daten gleichmäßig über alle Platten des Arrays","Sie beschleunigt das Lesen, weil alle Daten doppelt vorhanden sind","Sie verschlüsselt die Daten blockweise auf jeder einzelnen Platte"], a:0, e:"Parität = XOR über die Datenblöcke eines Stripes. Fällt eine Platte aus, ergibt das XOR der übrigen Blöcke den fehlenden. Nachteil: Jeder Schreibzugriff muss auch die Parität ändern (Write Penalty). RAID 2 nutzt statt einfacher Parität einen Hamming-Code."},
{t:"io", q:"Wodurch unterscheidet sich RAID 5 von RAID 4?", o:["Parität wird über alle Platten verteilt","Parität liegt auf einer eigenen Platte","Es werden zwei Paritäten berechnet","Daten werden zusätzlich gespiegelt"], a:0, e:"RAID 4: Block-Parität auf einer eigenen Platte (Write Penalty bei kleinen Writes). RAID 5: Parität round-robin verteilt; Ausfall einer beliebigen Platte führt nicht zu Datenverlust."},
{t:"io", q:"Was kennzeichnet RAID 6?", o:["Zwei Paritäten (P und Q), sehr hohe Verfügbarkeit, hoher Write Penalty","Zwei Paritäten (P und Q), sehr hohe Verfügbarkeit, kein Write Penalty","Eine verteilte Parität, sehr hohe Verfügbarkeit, hoher Write Penalty","Spiegelung plus Parität, mittlere Verfügbarkeit, kein Write Penalty"], a:0, e:"RAID 6: zwei Paritätsblöcke auf verschiedenen Platten; jeder Write betrifft zwei Paritätsblöcke."},
{t:"io", q:"Was bedeutet Striping?", o:["Daten werden in Stücke geteilt und reihum auf mehrere Platten verteilt","Daten werden vollständig auf zwei Platten gleichzeitig geschrieben","Daten werden mit Prüfsummen versehen und auf einer Platte gesichert","Daten werden nach Zugriffshäufigkeit auf schnelle Platten verschoben"], a:0, e:"Durch Striping können mehrere Platten gleichzeitig lesen und schreiben → höhere Transferrate. Allein (RAID 0) bringt es keine Redundanz."},
{t:"io", q:"Was ist RAID grundsätzlich?", o:["Mehrere physische Platten, die das OS als ein logisches Laufwerk sieht","Ein logisches Laufwerk, das auf mehrere Rechner im Netz verteilt ist","Eine einzelne Platte, die in mehrere logische Laufwerke geteilt ist","Ein Verfahren, das Daten auf den Platten automatisch komprimiert"], a:0, e:"Redundant Array of Independent Disks: Daten werden per Striping verteilt; redundante Informationen (Spiegelung/Parität) erlauben die Wiederherstellung bei Plattenausfall – außer bei RAID 0."},
{t:"io", q:"Wozu dient Double Buffering?", o:["Ein Puffer wird verarbeitet, während der andere befüllt wird","Jeder Block wird zur Sicherheit doppelt auf die Platte geschrieben","Der Puffer liegt einmal im Kernel und einmal im Gerät","Lese- und Schreibzugriffe nutzen getrennte Geräte"], a:0, e:"Buffering vermeidet Overhead und Ineffizienz. Varianten: No Buffering, Single Buffering, Double Buffering (zwei Puffer im OS)."},

// ---------- Virtualisierung ----------
{t:"virt", q:"Wofür steht das JVM-Prinzip „einmal schreiben, überall ausführen“ (Write Once, Run Anywhere)?", o:["Java-Code läuft unverändert auf jeder Plattform mit JVM","Java-Code wird einmal pro Plattform neu kompiliert","Java-Code läuft nur auf einer zertifizierten Hardware","Java-Code wird zur Laufzeit in Maschinencode übersetzt und verworfen"], a:0, e:"JVM = abstrakte Maschine mit Instruction Set, PC-Register, Stack, Heap (mit Garbage Collection) und Method Area."},
{t:"virt", q:"Was ist ein Hypervisor (VMM)?", o:["Software zwischen Hardware und VMs, die als Ressourcen-Broker agiert","Software innerhalb jeder VM, die deren Gast-OS überwacht","Hardware-Erweiterung der CPU für privilegierte Instruktionen","Ein Container-Runtime, die Anwendungen den Host-Kernel teilen lässt"], a:0, e:"Der Virtual Machine Monitor ermöglicht mehrere Betriebssysteme gleichzeitig auf einem Rechner."},
{t:"virt", q:"Warum ist das Kopieren einer VM gleichzeitig ein Backup des ganzen Servers?", o:["Weil eine VM vollständig in Dateien definiert ist","Weil der Hypervisor automatisch Snapshots anlegt","Weil VMs ihren Zustand nur im RAM halten","Weil die VM die Hardware des Hosts mitkopiert"], a:0, e:"Kopie umfasst OS, Anwendungen und Hardware-Konfiguration. Beim Einschalten entstehen zusätzliche Dateien für Logging, Paging usw."},
{t:"virt", q:"Was passiert, wenn ein Gast-OS unter einem Type-1-Hypervisor eine privilegierte Instruktion ausführt?", o:["Trap in den Hypervisor, der sie behandelt","Die Hardware führt sie direkt aus","Das Gast-OS behandelt sie selbst im Kernel Mode","Die Instruktion wird ignoriert"], a:0, e:"Gast-OS läuft im virtuellen Kernel Mode (eigentlich User Mode) → Trap on privileged instruction → Hypervisor im echten Kernel Mode."},
{t:"virt", q:"Was ist Paravirtualisierung?", o:["Das Gast-OS ist angepasst und ruft den Hypervisor direkt auf","Das Gast-OS ist unverändert, Instruktionen werden abgefangen","Mehrere Gast-OS teilen sich denselben Kernel","Die CPU übernimmt die Virtualisierung komplett in Hardware"], a:0, e:"Gast-OS (Linux/Windows) hat Paravirtualisierungs-Support und Treiber im Kernel → Hypervisor Calls statt Traps auf sensitive Instruktionen. In Linux-Distributionen seit 2008."},
{t:"virt", q:"Was sind AMD-V und Intel VT-x?", o:["Hardware-Erweiterungen für Virtualisierung","Type-1-Hypervisoren von AMD und Intel","Paravirtualisierungs-Treiber für Gast-OS","Befehlssätze für Container-Isolation"], a:0, e:"Intel bietet zusätzlich den Befehlssatz Virtual Machine Extensions (VMX). So muss der Hypervisor diese Funktionen nicht selbst nachbilden."},
{t:"virt", q:"Was ist eine Virtual Appliance?", o:["Anwendungen samt Gast-OS, verteilt als VM-Image","Anwendungen ohne Gast-OS, verteilt als Container-Image","Ein Hardware-Gerät mit vorinstalliertem Hypervisor","Ein Hypervisor, der nur eine einzige VM ausführt"], a:0, e:"Unabhängig von Hypervisor oder Prozessorarchitektur, läuft auf Type 1 und Type 2 – de-facto-Weg der Softwareverteilung."},
{t:"virt", q:"Was ist „Ballooning“?", o:["Ein Treiber im Gast zwingt das Gast-OS, Seiten auszulagern","Der Hypervisor teilt identische Seiten mehrerer VMs","Der Hypervisor teilt mehr RAM zu, als physisch vorhanden ist","Eine virtuelle Festplatte wächst automatisch mit"], a:0, e:"Der Balloon „bläht sich auf“, das Gast-OS lagert aus, danach kann der Hypervisor den RAM anderen VMs geben. Seiten teilen = Page Sharing, mehr zuteilen = Memory Overcommit."},
{t:"virt", q:"Welchen Vorteil bringt die Abstraktion des I/O-Pfads bei VMs?", o:["Live Migration und gemeinsame Nutzung von Netzwerkpfaden","Kein Prozessor-Overhead mehr für Netzwerkverkehr","Jede VM bekommt exklusiven Zugriff auf die Netzwerkkarte","Herstellerspezifische Treiber laufen direkt in der VM"], a:0, e:"Herstellerspezifische Treiber werden durch generische ersetzt → Hardwareunabhängigkeit. Trade-off: Hypervisor verwaltet allen Traffic (Prozessor-Overhead)."},
{t:"virt", q:"Was ist Live Migration?", o:["Eine laufende VM wird ohne Abschalten auf einen anderen Host verschoben","Eine VM wird heruntergefahren, kopiert und auf einem neuen Host gestartet","Ein Gast-OS wird während des Betriebs auf eine neue Version aktualisiert","Eine physische Maschine wird im laufenden Betrieb in eine VM umgewandelt"], a:0, e:"Möglich, weil die VM von der konkreten Hardware abstrahiert ist: Speicherinhalt und Zustand werden im laufenden Betrieb übertragen, generische Treiber laufen auf jedem Host. Nutzen: Wartung und Lastverteilung."},
{t:"virt", q:"Was ist der wesentliche Unterschied zwischen Containern und hypervisorbasierten VMs?", o:["Container teilen sich den Kernel des Host-OS","Container bringen jeweils ein eigenes Gast-OS mit","Container laufen nur auf einem Type-1-Hypervisor","Container emulieren einen kompletten physischen Server"], a:0, e:"Container laufen auf dem Host-Kernel und bieten isolierte Umgebungen → kein separates OS pro Anwendung, deutlich weniger Overhead."},
{t:"virt", q:"Wozu dienen Control Groups (cgroups) bei Containern?", o:["Sie begrenzen und isolieren die Ressourcen einer Gruppe von Prozessen","Sie emulieren für jeden Container eine eigene virtuelle Hardware","Sie fassen mehrere Container zu einer gemeinsamen VM zusammen","Sie verschlüsseln die Kommunikation zwischen den Containern"], a:0, e:"cgroups regeln CPU, Speicher, I/O usw. pro Container; über sie läuft auch die I/O-Indirektion zum physischen Treiber. Bei VMs übernimmt das der Hypervisor mit virtuellen Geräten."},
{t:"virt", q:"Was ist ein Docker Image?", o:["Eine unveränderliche Vorlage mit Anwendung und Abhängigkeiten, aus der Container entstehen","Ein laufender Container mit seinem aktuellen Zustand im Arbeitsspeicher","Eine vollständige VM mit eigenem Gast-Betriebssystem und eigenem Kernel","Ein Server, auf dem fertige Container zum Herunterladen bereitliegen"], a:0, e:"Image = Bauplan, Container = laufende Instanz davon. Weitere Docker-Komponenten: Client, Host, Engine, Machine, Registry, Hub."},
{t:"virt", q:"Was sind Microservices?", o:["Kleine, lose gekoppelte Dienste, die über klar definierte APIs kommunizieren","Kleine Programme, die direkt im Kernel als Module ausgeführt werden","Teile einer großen Anwendung, die immer gemeinsam deployt werden müssen","Kleine Hilfsprogramme, die nur innerhalb einer einzigen VM laufen"], a:0, e:"Definition nach NIST SP 800-180: lose gekoppelte, in sich geschlossene Services, die über ein Standardprotokoll und klar definierte APIs kommunizieren – herstellerunabhängig. Passt gut zu Containern."},
{t:"virt", q:"Welche Vorteile bieten Microservices?", o:["Kleinere deploybare Einheiten und präzise Skalierbarkeit","Weniger Netzwerkkommunikation und einfacheres Debugging","Ein gemeinsames Deployment und zentrale Datenbank","Enge Kopplung und herstellerspezifische Schnittstellen"], a:0, e:"Passt zu Continuous Delivery; einzelne Services lassen sich replizieren, um die Last genau für diesen Teil zu verteilen."},
{t:"virt", q:"Was ist Linux VServer?", o:["Virtualisierung mit nur einer Kopie des Linux-Kernels","Type-1-Hypervisor mit eigenem Kernel pro VM","Paravirtualisierter Linux-Gast unter Xen","Type-2-Hypervisor für Linux-Desktops"], a:0, e:"Open Source, kleine Kernel-Änderungen + Userland-Tools; der Kernel verwaltet alle Ressourcen, VMs haben eigene /home, /proc, /dev, /usr."},
{t:"virt", q:"Was ist ein Snapshot einer VM?", o:["Ein gespeicherter Zustand der VM, zu dem man später zurückkehren kann","Eine laufende Kopie der VM auf einem zweiten Host zur Ausfallsicherheit","Ein Bildschirmfoto des Gast-OS, das zur Fehlerdiagnose gespeichert wird","Ein Abbild der Host-Hardware, das in die VM übernommen wird"], a:0, e:"Weil eine VM vollständig in Dateien definiert ist, lässt sich ihr Zustand einfrieren und wiederherstellen – praktisch vor Updates oder Tests. Bekannte Type-1-Hypervisoren: VMware ESXi (VMKernel), Xen (Dom0/DomU), Hyper-V."},
{t:"virt", q:"Welche Funktion gehört zu den Aufgaben eines Hypervisors?", o:["Geräteemulation und Zugriffskontrolle","Kompilieren der Gast-Anwendungen","Scheduling der Threads im Gast-OS","Verwaltung der Dateisysteme im Gast"], a:0, e:"Hypervisor-Funktionen: Execution Management von VMs, Device Emulation & Access Control, privilegierte Operationen für Gäste, VM Lifecycle Management, Administration der Plattform."},

// ---------- Distributed ----------
{t:"dist", q:"Wie läuft der TCP-3-Way-Handshake ab?", o:["SYN → SYN-ACK → ACK","SYN → ACK → SYN-ACK","ACK → SYN → SYN-ACK","SYN → SYN → ACK"], a:0, e:"TCP ist verbindungsorientiert, garantiert Zustellung, erkennt Paketverlust und liefert in Reihenfolge."},
{t:"dist", q:"Welche Eigenschaft hat UDP?", o:["Verbindungslos, 64-Bit-Header, Datagramme können verschiedene Routen nehmen","Verbindungslos, 64-Bit-Header, garantiert die Reihenfolge der Datagramme","Verbindungsorientiert, 64-Bit-Header, Datagramme nehmen alle dieselbe Route","Verbindungslos, großer Header mit Sequenznummern für Neuübertragungen"], a:0, e:"UDP: schnell durch verbindungsloses Verhalten, kleiner 64-Bit-Header (8 Byte), keine Zustell- oder Reihenfolgegarantie."},
{t:"dist", q:"Worauf setzt HTTP/3 als Transport?", o:["QUIC über UDP","QUIC über TCP","TLS über TCP","SCTP über IP"], a:0, e:"HTTP/3 = HTTP-over-QUIC; QUIC implementiert TCPs Zuverlässigkeit und Bandbreitenmanagement auf UDP neu (verbindungsorientiert über verbindungslosem Transport)."},
{t:"dist", q:"Was ist Head-of-Line Blocking bei HTTP/2 über TCP?", o:["Ein verlorenes TCP-Paket hält alle Streams auf","Ein großer Stream verdrängt alle kleineren Streams","Der Server bearbeitet Requests strikt nacheinander","Zu große Header blockieren den ersten Request"], a:0, e:"Multiplexing passiert auf der Anwendungsschicht; für TCP ist alles ein einziger Bytestrom (Blackbox). Geht ein Paket verloren, warten alle folgenden."},
{t:"dist", q:"Wie löst QUIC das HoL-Blocking?", o:["Multiplexing auf der Transportschicht mit Stream-IDs","Multiplexing auf der Anwendungsschicht mit Stream-IDs","Eine eigene TCP-Verbindung pro Stream","Größere Empfangspuffer im Kernel"], a:0, e:"Jeder Stream ist für QUIC sichtbar; ein verlorenes Paket blockiert nur seinen eigenen Stream."},
{t:"dist", q:"Was ist der Unterschied zwischen Flow Control und Congestion Control?", o:["Flow Control schützt den Empfänger, Congestion Control das Netz","Flow Control schützt das Netz, Congestion Control den Empfänger","Flow Control regelt die Reihenfolge, Congestion Control die Verschlüsselung","Flow Control gibt es nur bei UDP, Congestion Control nur bei TCP"], a:0, e:"Flow Control: Der Sender schickt nicht mehr, als der Empfänger puffern kann (bei QUIC pro Stream). Congestion Control: Der Sender drosselt, wenn das Netz überlastet ist (QUIC z. B. mit NewReno oder CUBIC). UDP hat beides nicht."},
{t:"dist", q:"Wie ermöglicht QUIC Connection Migration (z. B. WLAN → Mobilfunk)?", o:["Über Connection IDs statt IP/Port","Über die MAC-Adresse des Geräts","Über einen neuen 3-Way-Handshake","Über die Session-ID im TLS-Ticket"], a:0, e:"QUIC startet mit einer Liste von Connection IDs; nach einer Migration wird eine andere ID verwendet, sodass Angreifer die Verbindung schwerer zuordnen können."},
{t:"dist", q:"Warum lässt sich QUIC leichter aktualisieren als TCP?", o:["QUIC läuft im User Space, TCP im Kernel","QUIC läuft im Kernel, TCP im User Space","QUIC ist in der Netzwerkkarte implementiert","QUIC wird von den Routern aktualisiert"], a:0, e:"Neue Funktionen können ohne Änderungen am Kernel integriert werden. Header-Verschlüsselung verringert zudem die Drop-Wahrscheinlichkeit durch Middleboxes."},
{t:"dist", q:"Was ist eine offene Herausforderung von HTTP/3?", o:["UDP wird in manchen Netzen blockiert → Fallback auf HTTP/2","QUIC unterstützt keine Verschlüsselung der Header","HTTP/3 braucht mehr Handshakes als HTTP/2","QUIC muss für jedes Update in den Kernel"], a:0, e:"Weitere: Versionsaushandlung bei der ersten Verbindung, verschlüsselte Metadaten erschweren Netzbetreibern die Arbeit (Firewalls), unterschiedliche Implementierungsqualität."},
{t:"dist", q:"Was bedeutet „persistente Verbindung mit Pipelining der Requests“ bei HTTP?", o:["Eine Verbindung, Requests ohne Warten auf Antworten","Eine Verbindung, Requests strikt nacheinander","Mehrere Verbindungen, Requests strikt nacheinander","Mehrere Verbindungen, Requests gleichzeitig"], a:0, e:"(a) mehrere Verbindungen, sequentiell; (b) persistente Verbindung, sequentiell; (c) persistente Verbindung, pipelined."},
{t:"dist", q:"Was ist ein eingebauter Vorteil von QUIC?", o:["Verschlüsselung ist fester Bestandteil","Es kommt ganz ohne Flow Control aus","Es garantiert eine feste Route pro Paket","Es läuft ausschließlich im Kernel"], a:0, e:"Vorteile: weniger Performanceprobleme, Security eingebaut, schnellere Verbreitung, kein HoL-Blocking, weniger Handshakes."},
{t:"dist", q:"Was bedeutet Multiplexing im Kontext von HTTP?", o:["Mehrere Byteströme über eine Verbindung","Ein Bytestrom über mehrere Verbindungen","Ein Request an mehrere Server gleichzeitig","Mehrere Antworten in einem einzigen Paket"], a:0, e:"Byte Stream: Bytefolge in Paketen unterschiedlicher Größe. Multiplexing: eine Verbindung für mehrere Byteströme."},
// ---------- Erweiterung: Grundlagen ----------
{t:"intro", q:"Warum dürfen Anwendungen privilegierte Instruktionen nicht selbst ausführen?", o:["Sonst könnte jedes Programm das System und andere Prozesse beschädigen","Weil privilegierte Instruktionen im User Mode langsamer ablaufen","Weil der Compiler privilegierte Instruktionen nicht übersetzen kann","Weil privilegierte Instruktionen nur auf Multicore-CPUs existieren"], a:0, e:"Privilegierte Instruktionen (z. B. I/O-Zugriff, Interrupts abschalten, Speicherschutz ändern) könnten den Schutz zwischen Prozessen aushebeln. Deshalb erlaubt die CPU sie nur im Kernel Mode; Programme müssen den Kernel per Systemaufruf bitten."},
{t:"intro", q:"Was passiert, wenn ein Programm im User Mode eine privilegierte Instruktion ausführt?", o:["Die CPU löst einen Trap aus und der Kernel übernimmt","Die Instruktion wird ausgeführt, aber nur protokolliert","Die CPU wechselt automatisch dauerhaft in den Kernel Mode","Die Instruktion wird ohne jede Reaktion übersprungen"], a:0, e:"Die Hardware erkennt den Verstoß und springt per Trap (Exception) in den Kernel. Der Kernel entscheidet dann, meist wird das Programm beendet. Genau dieser Mechanismus macht auch Trap-and-Emulate bei Hypervisoren möglich."},
{t:"intro", q:"Was meint man mit „das Betriebssystem als Ressourcenverwalter“?", o:["Es teilt CPU, Speicher und Geräte geordnet zwischen Programmen auf","Es kauft und installiert bei Bedarf automatisch neue Hardware","Es überlässt jedem Programm exklusiv alle Ressourcen der Reihe nach","Es verwaltet nur den Festplattenplatz der einzelnen Benutzer"], a:0, e:"Zwei Sichten auf das OS: als erweiterte Maschine (schöne Abstraktionen) und als Ressourcenverwalter (Multiplexing in Zeit, z. B. CPU, und im Raum, z. B. Speicher)."},
{t:"intro", q:"Welche Abstraktion bietet das OS z. B. für eine Festplatte an?", o:["Dateien und Verzeichnisse statt Sektoren und Spuren","Sektoren und Spuren statt Dateien und Verzeichnisse","Rohe Geräteregister, die das Programm direkt beschreibt","Physische Speicheradressen statt Blocknummern"], a:0, e:"Programme arbeiten mit Dateien (open, read, write), ohne Sektoren, Spuren oder Controller-Befehle zu kennen. Das ist die „schöne Schnittstelle“ über der „hässlichen“ Hardware."},
{t:"intro", q:"Was ist ein Cache-Hit?", o:["Die gesuchten Daten liegen bereits im Cache","Die gesuchten Daten müssen aus dem RAM geholt werden","Der Cache ist voll und muss geleert werden","Zwei Prozesse greifen gleichzeitig auf den Cache zu"], a:0, e:"Hit: Daten im Cache → schneller Zugriff. Miss: Daten fehlen → Block wird aus dem langsameren Speicher geladen (und ein anderer ggf. verdrängt). Dank Lokalität ist die Hit-Rate meist hoch."},
{t:"intro", q:"Wozu dient das Instruction Register (IR)?", o:["Es hält die gerade geholte Instruktion, die ausgeführt wird","Es hält die Adresse der als Nächstes zu holenden Instruktion","Es hält das Ergebnis der letzten arithmetischen Operation","Es hält die Nummer des gerade laufenden Prozesses"], a:0, e:"Fetch: Die Instruktion an der Adresse im PC wird ins IR geladen, der PC erhöht. Execute: Der Prozessor dekodiert das IR und führt aus."},
{t:"intro", q:"Was ist ein Interrupt?", o:["Ein Signal, das den laufenden Ablauf für ein Ereignis unterbricht","Ein Befehl, mit dem ein Programm sich selbst dauerhaft beendet","Ein Fehler im Programmcode, der vom Compiler gemeldet wird","Eine Pause, die der Scheduler zwischen zwei Prozessen einlegt"], a:0, e:"Quellen: Hardware (I/O fertig, Timer), Programmfehler (z. B. Division durch 0) oder Hardwarefehler. Die CPU sichert den Zustand, springt in den Interrupt Handler und setzt danach das unterbrochene Programm fort."},
{t:"intro", q:"Warum sind Interrupts effizienter als ständiges Abfragen (Polling) eines Geräts?", o:["Die CPU kann rechnen, bis das Gerät sich selbst meldet","Interrupts übertragen die Daten schneller über den Bus","Beim Polling muss das Gerät jedes Mal neu gestartet werden","Interrupts benötigen keinerlei Zustandssicherung der CPU"], a:0, e:"Beim Polling verschwendet die CPU Zeit mit Nachfragen (busy waiting). Mit Interrupts startet sie die I/O, macht anderes und wird beim Abschluss unterbrochen."},
{t:"intro", q:"Was macht der Prozessor, bevor er den Interrupt Handler startet?", o:["Er sichert PC und Statusinformationen des unterbrochenen Programms","Er beendet das unterbrochene Programm und gibt dessen Speicher frei","Er leert den Cache, damit der Handler saubere Daten sieht","Er wartet, bis alle anderen Prozesse ihre Zeitscheibe beendet haben"], a:0, e:"Nur so kann das Programm nach dem Handler genau dort weiterlaufen, wo es unterbrochen wurde. Danach lädt die CPU die Startadresse des passenden Handlers in den PC."},
{t:"intro", q:"Warum gibt es im Adressraum eines Prozesses eine Lücke (Gap) zwischen Data und Stack?", o:["Damit Heap und Stack aufeinander zu wachsen können","Damit der Kernel dort seine eigenen Daten ablegt","Damit Programmcode dort zur Laufzeit nachgeladen wird","Damit Speicherschutz zwischen zwei Prozessen entsteht"], a:0, e:"Daten (Heap) wachsen nach oben, der Stack wächst von FFFF nach unten. Die Lücke ist der freie Platz, den beide nach Bedarf nutzen."},
{t:"intro", q:"Was liegt auf dem Stack eines Prozesses?", o:["Lokale Variablen, Parameter und Rücksprungadressen von Funktionen","Der Maschinencode des Programms","Globale Variablen, die beim Start initialisiert werden","Die Liste der vom Prozess geöffneten Dateien"], a:0, e:"Bei jedem Funktionsaufruf wird ein Stack Frame angelegt und beim Rücksprung wieder entfernt. Code liegt im Text-, globale Variablen im Data-Segment, offene Dateien verwaltet das OS."},
{t:"intro", q:"Was ist ein Mount Point?", o:["Das Verzeichnis, unter dem ein anderes Dateisystem eingehängt wird","Die Partition, auf der das Betriebssystem installiert ist","Der Treiber, der ein USB-Laufwerk erkennt","Die erste Datei, die beim Booten geladen wird"], a:0, e:"Beispiel: Das USB-Dateisystem wird unter /mnt/usb eingehängt; danach erscheinen seine Dateien als Teil des einen Verzeichnisbaums."},
{t:"intro", q:"Was ist der Vorteil, Dateisysteme in einen gemeinsamen Baum zu mounten?", o:["Programme sehen einen einheitlichen Namensraum, egal auf welchem Gerät Dateien liegen","Alle Dateien werden dadurch automatisch auf eine Platte zusammenkopiert","Das Root-Dateisystem wird beim Mounten vergrößert und neu formatiert","Laufwerke können danach nur noch gelesen und nicht beschrieben werden"], a:0, e:"UNIX kennt keine Laufwerksbuchstaben: Alles hängt unter /. Ob /home auf einer anderen Platte oder einem USB-Stick liegt, merkt das Programm nicht."},
{t:"intro", q:"Was unterscheidet Hyperthreading (SMT) von echtem Multicore?", o:["SMT: ein Kern mit mehreren Hardware-Threads; Multicore: mehrere vollständige Kerne","SMT: mehrere vollständige Kerne; Multicore: ein Kern mit mehreren Threads","SMT: mehrere Chips auf einer Platine; Multicore: mehrere Rechner im Netz","Es gibt keinen Unterschied, beides bezeichnet dieselbe Technik"], a:0, e:"Bei SMT teilen sich zwei Hardware-Threads die Rechenwerke eines Kerns (z. B. um Wartezeiten zu überbrücken). Multicore hat mehrere Kerne mit je eigenen Rechenwerken und L1/L2-Caches."},
{t:"intro", q:"Warum teilen sich die Kerne eines Multicore-Prozessors oft den L3-Cache?", o:["Gemeinsame Daten müssen nicht mehrfach gehalten werden und Kerne tauschen sie schnell aus","Weil jeder Kern sonst keinen eigenen L1- und L2-Cache haben dürfte","Weil der L3-Cache nur Instruktionen speichert, die alle Kerne gleich brauchen","Weil der Hauptspeicher bei Multicore-Prozessoren ganz entfällt"], a:0, e:"Beispiel i7-5960X: L1 und L2 pro Kern, 20 MB L3 geteilt. Geteilter Cache spart Platz bei gemeinsamen Daten, bringt aber Konkurrenz (→ contention-aware Scheduling)."},
{t:"intro", q:"Was ist Time-Sharing?", o:["Viele Benutzer arbeiten interaktiv, die CPU wird in kurzen Zeitscheiben verteilt","Jobs werden gesammelt und ohne Interaktion nacheinander ausgeführt","Jeder Benutzer bekommt einen eigenen physischen Prozessor zugeteilt","Rechenaufträge werden zu festen Uhrzeiten automatisch gestartet"], a:0, e:"Ziel ist eine kurze Antwortzeit: Durch schnelles Umschalten hat jeder Nutzer das Gefühl, den Rechner allein zu nutzen. Batch-Systeme optimieren dagegen den Durchsatz."},
{t:"intro", q:"Welches Ziel optimiert ein Batch-System hauptsächlich?", o:["Durchsatz und Auslastung","Antwortzeit für Benutzer","Einhalten harter Deadlines","Fairness zwischen Nutzern"], a:0, e:"Ohne Interaktion zählt, wie viele Jobs pro Zeit fertig werden und dass die teure CPU nie leerläuft. Interaktive Systeme optimieren die Antwortzeit, Echtzeitsysteme Deadlines."},
// ---------- Erweiterung: OS-Strukturen ----------
{t:"oss", q:"Was kennzeichnet ein geschichtetes Betriebssystem (Layered System)?", o:["Jede Schicht nutzt nur die Dienste der direkt darunterliegenden Schicht","Alle Prozeduren dürfen sich beliebig gegenseitig aufrufen","Nur ein minimaler Kern läuft im Kernel Mode, der Rest als Prozesse","Jede Schicht läuft auf einem eigenen Prozessor"], a:0, e:"Vorteil: übersichtlich, Schichten einzeln testbar. Nachteil: Aufrufe müssen alle Schichten durchlaufen, und die richtige Reihenfolge der Schichten ist schwer festzulegen."},
{t:"oss", q:"Was ist ein Vorteil eines Microkernels gegenüber einem monolithischen Kernel?", o:["Ein abgestürzter Treiber reißt nicht das ganze System mit","Systemaufrufe sind schneller, weil weniger Moduswechsel nötig sind","Alle Dienste teilen sich einen Adressraum und kommunizieren direkt","Der Kernel enthält alle Treiber und ist dadurch leichter zu warten"], a:0, e:"Treiber und Dienste laufen als isolierte User-Prozesse – Fehler bleiben eingegrenzt und Teile lassen sich austauschen. Der Preis: Kommunikation über Nachrichten und mehr Moduswechsel."},
{t:"oss", q:"Warum ist ein monolithischer Kernel meist schneller als ein Microkernel?", o:["Dienste rufen sich direkt im Kernel auf statt über Nachrichten zwischen Prozessen","Er läuft komplett im User Mode und spart dadurch alle Traps","Er enthält weniger Code und passt dadurch vollständig in den Cache","Er verzichtet auf Speicherschutz zwischen den Anwendungen"], a:0, e:"Ein Funktionsaufruf im selben Adressraum ist billig; beim Microkernel müssen Nachrichten zwischen Prozessen ausgetauscht und Kontexte gewechselt werden. Linux und Windows sind daher (weitgehend) monolithisch bzw. hybrid."},
{t:"oss", q:"Was ist ein Type-2-Hypervisor?", o:["Ein Hypervisor, der als Anwendung auf einem Host-Betriebssystem läuft","Ein Hypervisor, der direkt auf der Hardware ohne Host-OS läuft","Ein Hypervisor, der nur Container und keine VMs starten kann","Ein Hypervisor, der in die CPU-Hardware fest eingebaut ist"], a:0, e:"Beispiele: VirtualBox, UTM, VMware Workstation. Bequem auf dem Desktop, aber jede Hardwareoperation geht zusätzlich durch das Host-OS → mehr Overhead als Type 1."},
{t:"oss", q:"Was ist bei Windows ein Job Object?", o:["Eine Gruppe von Prozessen, die gemeinsam verwaltet und begrenzt wird","Eine Ausführungseinheit, die die Anwendung selbst manuell umschaltet","Eine Sammlung von Worker-Threads für asynchrone Aufgaben","Ein geplanter Auftrag, der zu einer festen Uhrzeit startet"], a:0, e:"Windows-Hierarchie: Job (Gruppe von Prozessen, z. B. mit Quoten) → Process (Ressourcen) → Thread (Ausführung) → Fiber (von der App geschaltet). Thread Pool = Worker-Threads."},
{t:"oss", q:"Was ist ein Thread Pool?", o:["Eine Menge bereits erzeugter Threads, die Aufgaben nacheinander abarbeiten","Ein Speicherbereich, in dem alle Threads ihre Stacks gemeinsam ablegen","Eine Gruppe von Prozessen, die gemeinsam Ressourcenlimits bekommen","Ein Scheduler, der für jede neue Aufgabe einen neuen Thread erzeugt"], a:0, e:"Threads werden einmal erzeugt und wiederverwendet – das spart die Kosten für Erzeugen und Beenden und begrenzt die Anzahl gleichzeitiger Threads. Beispiele: Windows Thread Pool, GCD unter macOS."},
{t:"oss", q:"Warum beendet Android bei RAM-Knappheit zuerst „Empty“-Prozesse?", o:["Sie enthalten keine aktive Komponente und dienen nur als Cache für schnellen Neustart","Sie verbrauchen den meisten Speicher aller Prozesse im System","Sie sind abgestürzt und müssen ohnehin neu gestartet werden","Sie gehören immer zu Systemdiensten, die sich selbst neu starten"], a:0, e:"Präzedenz absteigend: Foreground → Visible → Service → Background → Empty. Beendet wird von unten. Ein Empty-Prozess wird nur behalten, damit die App beim nächsten Öffnen schneller startet."},
{t:"oss", q:"Welcher Android-Prozess hat die höchste Präzedenz?", o:["Der Foreground-Prozess, mit dem der Nutzer gerade interagiert","Der Service-Prozess, der im Hintergrund Musik abspielt","Der Visible-Prozess, der teilweise noch sichtbar ist","Der Background-Prozess, der am längsten läuft"], a:0, e:"Was der Nutzer gerade benutzt, wird als Letztes beendet. Reihenfolge: Foreground → Visible → Service → Background → Empty."},
{t:"oss", q:"Warum beendet Android Prozesse, statt sie wie ein Desktop-OS per Swapping auszulagern?", o:["Flash verträgt viele Schreibvorgänge schlecht, Apps laden ihren Zustand neu","Android-Geräte besitzen grundsätzlich keinen dauerhaften Speicher","Swapping ist unter Linux-Kerneln technisch überhaupt nicht möglich","Beendete Prozesse verbrauchen weniger Strom als ausgelagerte"], a:0, e:"Mobilgeräte haben wenig RAM und Flash als Speicher; ständiges Auslagern würde Flash abnutzen und wäre langsam. Apps speichern ihren Zustand und werden bei Bedarf neu gestartet."},
{t:"oss", q:"Was ist ein ladbares Kernelmodul (z. B. unter Linux)?", o:["Code, der zur Laufzeit in den Kernel geladen wird, etwa ein Treiber","Ein Benutzerprogramm, das mit Root-Rechten im User Mode läuft","Eine Bibliothek, die Anwendungen beim Start dazubinden","Eine Konfigurationsdatei, die der Kernel beim Booten liest"], a:0, e:"Module erweitern einen monolithischen Kernel ohne Neukompilieren oder Neustart (z. B. ein USB-Treiber). Sie laufen danach im Kernel Mode – ein fehlerhaftes Modul kann also das System gefährden."},
{t:"oss", q:"Was ist eine Shell?", o:["Ein Kommandointerpreter, der Befehle des Nutzers als Programme startet","Die innerste Schicht des Kernels, die die Hardware steuert","Ein Schutzmechanismus, der Prozesse voneinander isoliert","Eine grafische Oberfläche, die direkt im Kernel Mode läuft"], a:0, e:"Die Shell (z. B. bash) ist ein normales Programm im User Mode. Sie liest Befehle, erzeugt Prozesse (fork/exec) und gibt Ergebnisse aus – sie gehört nicht zum Kernel."},
{t:"oss", q:"Was bedeutet das UNIX-Prinzip „Alles ist eine Datei“ (Everything is a file)?", o:["Auch Geräte und Pipes werden über Dateioperationen wie read und write angesprochen","Alle Programme müssen ihre Daten ausschließlich in Dateien speichern","Jeder Prozess wird als Datei auf der Festplatte abgelegt","Das Betriebssystem besteht nur aus einer einzigen großen Datei"], a:0, e:"Geräte erscheinen z. B. unter /dev, Prozessinformationen unter /proc. Programme brauchen so nur eine einheitliche Schnittstelle (open/read/write/close) – das Ziel „Generality“."},
// ---------- Erweiterung: Prozesse ----------
{t:"proc", q:"Was ist der Unterschied zwischen Programm und Prozess?", o:["Programm: passive Datei mit Code; Prozess: dieses Programm in Ausführung mit Zustand","Programm: laufende Instanz; Prozess: die zugehörige Datei auf der Platte","Programm: läuft im Kernel Mode; Prozess: läuft im User Mode","Es gibt keinen Unterschied, beide Begriffe meinen dasselbe"], a:0, e:"Aus einem Programm (z. B. dem Browser) können mehrere Prozesse gleichzeitig entstehen – jeder mit eigenem Adressraum, PC, Registern und Ressourcen."},
{t:"proc", q:"Warum gibt es den Zustand „Blocked“?", o:["Damit ein wartender Prozess nicht unnötig ausgewählt wird","Damit ein Prozess vor dem Start noch geprüft werden kann","Damit ein beendeter Prozess noch kurz im Speicher bleibt","Damit Prozesse mit niedriger Priorität seltener laufen"], a:0, e:"Wartet ein Prozess auf I/O, wäre es Verschwendung, ihn auszuwählen. Erst wenn das Ereignis eintritt (Event Occurs), wird er wieder Ready."},
{t:"proc", q:"Warum ist der Process Control Block (PCB) so wichtig?", o:["Mit ihm kann ein unterbrochener Prozess später genau dort fortgesetzt werden","Er enthält den kompletten Programmcode, der ausgeführt werden soll","Er speichert die Benutzerdaten des Prozesses dauerhaft auf der Platte","Er ersetzt die Page Table bei der Adressübersetzung"], a:0, e:"Im PCB stehen Identifier, Zustand, Priorität, PC, Register (Context Data), Speicher-Pointer, I/O-Status und Accounting. Ohne ihn wären Unterbrechung und Multiprogramming nicht möglich."},
{t:"proc", q:"Warum ist ein Mode Switch billiger als ein Prozesswechsel?", o:["Der Prozess bleibt derselbe, es wird kein neuer Kontext geladen","Beim Mode Switch werden alle Caches und Page Tables neu geladen","Ein Mode Switch läuft komplett ohne Beteiligung der Hardware ab","Ein Mode Switch ist nur bei User-Level Threads möglich"], a:0, e:"Mode Switch: nur User ↔ Kernel Mode (z. B. bei Syscall/Interrupt). Prozesswechsel: zusätzlich PCB sichern, Queues aktualisieren, Speicherverwaltung umschalten, neuen Kontext laden."},
{t:"proc", q:"Was macht fork() unter UNIX?", o:["Erzeugt eine Kopie des aufrufenden Prozesses; beide laufen danach weiter","Ersetzt das Programm des aufrufenden Prozesses durch ein neues","Beendet den aufrufenden Prozess und startet ihn neu","Erzeugt einen neuen Thread im selben Adressraum"], a:0, e:"Nach fork() existieren Eltern und Kind; der Rückgabewert unterscheidet sie (Kind: 0, Eltern: PID des Kindes). Ein neues Programm lädt erst exec()."},
{t:"proc", q:"Wie kann ein Programm nach fork() erkennen, ob es Eltern- oder Kindprozess ist?", o:["Am Rückgabewert: das Kind bekommt 0, der Elternprozess die PID des Kindes","Am Rückgabewert: das Kind bekommt seine PID, der Elternprozess 0","An einer Umgebungsvariable, die das OS nur im Kind setzt","Gar nicht – beide Prozesse sind vollständig identisch"], a:0, e:"Typisches Muster: if (pid == 0) { /* Kind */ } else if (pid > 0) { /* Eltern */ } else { /* Fehler (-1) */ }."},
{t:"proc", q:"Aus welchen Gründen kann ein Prozess beendet werden?", o:["Normales Ende, Fehler, Zeitlimit oder Abbruch durch andere","Nur durch normales Ende oder durch Ausschalten des Rechners","Nur wenn der Elternprozess das ausdrücklich erlaubt","Nur wenn alle seine Threads gerade blockiert sind"], a:0, e:"Beispiele: exit(), Speicherschutzverletzung, arithmetischer Fehler, Zeitlimit, Eingriff des OS oder Elternprozesses (kill), Speichermangel."},
{t:"proc", q:"Was ist ein Zombie-Prozess unter UNIX?", o:["Ein beendeter Prozess, dessen Exit-Status der Elternprozess noch nicht abgeholt hat","Ein Prozess, der endlos läuft und auf keine Signale mehr reagiert","Ein Kindprozess, dessen Elternprozess bereits beendet ist","Ein Prozess, der ausgelagert wurde und auf Rückkehr in den RAM wartet"], a:0, e:"Der Prozess läuft nicht mehr, aber sein Eintrag in der Prozesstabelle bleibt, bis der Elternprozess wait() aufruft (Zustand Exit im 5-Zustands-Modell)."},
{t:"proc", q:"Warum bleibt ein Prozess im Zustand „Exit“ noch kurz in den OS-Tabellen?", o:["Damit Accounting-Daten und Exit-Status noch abgefragt werden können","Damit er bei Bedarf ohne Neustart weiterlaufen kann","Damit seine geöffneten Dateien weiter beschrieben werden","Damit andere Prozesse seinen Speicher übernehmen können"], a:0, e:"Im 5-Zustands-Modell ist Exit ein eigener Zustand: Der Prozess läuft nicht mehr, aber Informationen (z. B. für den Elternprozess oder Statistik) bleiben, bis sie abgeholt sind."},
{t:"proc", q:"Jeder Prozess wartet 80 % seiner Zeit auf I/O. Wie hoch ist die CPU-Auslastung bei 2 Prozessen (vereinfachtes Modell 1 − pⁿ)?", o:["36 %","20 %","40 %","64 %"], a:0, e:"Die CPU ist nur leer, wenn alle Prozesse gleichzeitig warten: 0,8² = 0,64. Auslastung = 1 − 0,64 = 0,36 = 36 %. Mit mehr Prozessen steigt sie (n = 5: 1 − 0,8⁵ ≈ 67 %)."},
{t:"proc", q:"Warum erhöht man den Grad der Multiprogrammierung bei I/O-lastigen Prozessen?", o:["Damit fast immer ein Prozess bereit ist, während andere auf I/O warten","Damit jeder Prozess eine längere Zeitscheibe bekommt","Damit weniger Kontextwechsel zwischen den Prozessen nötig sind","Damit die I/O-Geräte ihre Daten schneller übertragen"], a:0, e:"Je mehr Zeit Prozesse mit Warten verbringen, desto mehr Prozesse braucht man, damit die CPU nicht leerläuft (Auslastung ≈ 1 − pⁿ)."},
// ---------- Erweiterung: Threads ----------
{t:"thr", q:"Was sagt Amdahls Gesetz aus?", o:["Der serielle Anteil eines Programms begrenzt den möglichen Speedup","Die Rechenleistung von Chips verdoppelt sich etwa alle zwei Jahre","Mit doppelt so vielen Prozessoren halbiert sich immer die Laufzeit","Parallele Programme sind grundsätzlich schneller als serielle"], a:0, e:"Speedup = 1 / ((1 − f) + f/N). Selbst mit unendlich vielen Prozessoren gilt höchstens 1 / (1 − f)."},
{t:"thr", q:"Amdahls Gesetz: f = 0,75 parallelisierbar, N = 3 Prozessoren. Speedup?", o:["2","3","2,25","1,5"], a:0, e:"1 / (0,25 + 0,75/3) = 1 / (0,25 + 0,25) = 1 / 0,5 = 2."},
{t:"thr", q:"Was bedeutet Responsiveness als Vorteil von Threads?", o:["Ein Thread kann auf den Nutzer reagieren, während ein anderer lange rechnet","Threads werden vom Scheduler immer bevorzugt und laufen früher","Jeder Thread bekommt automatisch einen eigenen Prozessorkern","Threads können nie blockieren und reagieren daher sofort"], a:0, e:"Beispiel Textverarbeitung: ein Thread für Eingaben, einer für Formatierung, einer für automatisches Speichern. Die Oberfläche bleibt bedienbar."},
{t:"thr", q:"Warum nutzt ein Web-Server Threads statt für jede Anfrage einen neuen Prozess?", o:["Threads sind billiger zu erzeugen und teilen sich z. B. den Seiten-Cache","Prozesse können grundsätzlich keine Netzwerkverbindungen öffnen","Threads laufen im Kernel Mode und sind dadurch schneller","Mit Prozessen könnten nicht mehrere Anfragen gleichzeitig laufen"], a:0, e:"Alle Worker-Threads teilen den Adressraum, also auch den Web Page Cache. Ein neuer Prozess bräuchte einen eigenen Adressraum und eine Kopie aller Ressourcen."},
{t:"thr", q:"Was passiert bei User-Level Threads, wenn ein Thread einen blockierenden Systemaufruf macht?", o:["Der ganze Prozess blockiert, auch alle anderen Threads","Nur dieser Thread blockiert, die anderen laufen weiter","Der Kernel wählt automatisch einen anderen Thread desselben Prozesses","Der Systemaufruf wird abgelehnt, weil ULT keine Syscalls dürfen"], a:0, e:"Der Kernel kennt nur den Prozess, nicht die Threads. Blockiert der Prozess, kann die Thread-Bibliothek nicht umschalten. Abhilfe: Jacketing (nichtblockierende Aufrufe) oder KLT."},
{t:"thr", q:"Was ist ein hybrides Thread-Modell (M:N)?", o:["Mehrere User-Level Threads werden auf mehrere Kernel-Level Threads abgebildet","Jeder User-Level Thread bekommt genau einen eigenen Kernel-Level Thread","Alle User-Level Threads laufen auf einem einzigen Kernel-Level Thread","Threads und Prozesse werden zu einer gemeinsamen Einheit zusammengelegt"], a:0, e:"Kombiniert die Vorteile: schnelles Umschalten im User Space und trotzdem echte Parallelität bzw. kein Blockieren des ganzen Prozesses. Beispiel: früher Solaris."},
{t:"thr", q:"Welches Thread-Modell nutzen Linux und Windows heute hauptsächlich?", o:["1:1 – jeder Thread ist ein Kernel-Level Thread","N:1 – alle Threads auf einem Kernel-Thread","M:N – viele ULT auf wenige KLT","Gar keins – sie kennen nur Prozesse"], a:0, e:"Bei 1:1 kann der Kernel jeden Thread einzeln schedulen und auf mehrere Kerne verteilen. Der höhere Aufwand pro Wechsel wird dafür in Kauf genommen."},
{t:"thr", q:"Was ist der Vorteil eines Thread-Pools gegenüber einem neuen Thread pro Aufgabe?", o:["Erzeugungskosten entfallen und die Anzahl gleichzeitiger Threads bleibt begrenzt","Jede Aufgabe bekommt garantiert einen eigenen Prozessorkern","Aufgaben werden strikt nacheinander und dadurch ohne Konflikte erledigt","Threads aus dem Pool brauchen keinen eigenen Stack mehr"], a:0, e:"Bei vielen kurzen Aufgaben (z. B. Web-Anfragen) wäre ständiges Erzeugen/Beenden teuer, und zu viele Threads überlasten das System. GCD unter macOS arbeitet genau so."},
{t:"thr", q:"Was ist bei Grand Central Dispatch ein „Block“?", o:["Eine in sich geschlossene Arbeitseinheit, die in eine Queue gelegt wird","Ein blockierter Thread, der auf ein I/O-Ereignis wartet","Ein Speicherblock, den mehrere Threads gemeinsam nutzen","Ein Abschnitt, in dem nur ein Thread gleichzeitig laufen darf"], a:0, e:"Der Programmierer beschreibt nur die Arbeit (Block) und legt sie in eine Dispatch Queue; GCD verteilt sie auf seinen Thread-Pool. So muss die App keine Threads selbst verwalten."},
{t:"thr", q:"Kann bei Kernel-Level Threads ein Thread blockieren, während andere Threads desselben Prozesses weiterlaufen?", o:["Ja, der Kernel kann einen anderen Thread des Prozesses auswählen","Nein, bei KLT blockiert immer der ganze Prozess","Nur wenn der Prozess genau zwei Threads besitzt","Nur auf Systemen mit einem einzigen Prozessorkern"], a:0, e:"Das ist ein zentraler Vorteil von KLT: Der Kernel kennt jeden Thread. Bei ULT blockiert dagegen der ganze Prozess."},
{t:"thr", q:"Warum können User-Level Threads nicht parallel auf mehreren Kernen laufen?", o:["Der Kernel sieht nur einen Prozess und plant ihn auf genau einem Kern ein","Die Thread-Bibliothek sperrt absichtlich alle anderen Kerne","ULT haben keinen eigenen Program Counter","Mehrere Kerne können keinen gemeinsamen Adressraum nutzen"], a:0, e:"Die Thread-Verwaltung liegt komplett in der Bibliothek im User Space. Der Kernel weiß nichts von mehreren Threads und kann sie daher nicht verteilen."},
// ---------- Erweiterung: Scheduling Basics ----------
{t:"sch1", q:"Warum kann der Medium-Term Scheduler bei Speichermangel helfen?", o:["Er lagert ganze Prozesse aus und senkt so den Grad der Multiprogrammierung","Er wählt in kürzeren Abständen den nächsten Prozess für die CPU","Er lehnt neue Programme ab, bevor sie überhaupt Prozesse werden","Er komprimiert die Page Tables aller Prozesse im Hauptspeicher"], a:0, e:"Swapping-out bei Speicherbedarf, Swapping-in, wenn wieder Platz ist. So lässt sich z. B. Thrashing bekämpfen."},
{t:"sch1", q:"Was misst die Response Time?", o:["Die Zeit von der Anfrage bis zur ersten Reaktion des Systems","Die Zeit von der Ankunft bis zur vollständigen Fertigstellung","Die Anzahl der Prozesse, die pro Zeiteinheit fertig werden","Den Anteil der Zeit, in dem die CPU beschäftigt ist"], a:0, e:"Für interaktive Nutzer zählt, wie schnell das System überhaupt reagiert – nicht, wann alles fertig ist. Response Time ist benutzerorientiert."},
{t:"sch1", q:"Was ist Throughput (Durchsatz)?", o:["Die Anzahl fertiggestellter Prozesse pro Zeiteinheit","Die Zeit, bis ein einzelner Prozess fertig ist","Die Zeit, die ein Prozess in der Ready-Queue wartet","Die Datenmenge, die pro Sekunde über den Bus fließt"], a:0, e:"Throughput ist ein systemorientiertes Kriterium und das Hauptziel von Batch-Systemen, zusammen mit der CPU-Auslastung."},
{t:"sch1", q:"Was ist ein Nachteil von preemptivem Scheduling?", o:["Mehr Kontextwechsel und damit mehr Verwaltungsaufwand","Ein einzelner Prozess kann die CPU unbegrenzt blockieren","Kurze Prozesse müssen hinter langen warten","Interaktive Prozesse reagieren dadurch langsamer"], a:0, e:"Preemption verbessert Antwortzeiten und verhindert Monopolisierung, kostet aber Overhead durch häufigere Wechsel – und gemeinsame Daten müssen synchronisiert werden."},
{t:"sch1", q:"Warum ist non-preemptive Scheduling für interaktive Systeme schlecht geeignet?", o:["Ein langer Rechenjob kann alle anderen lange warten lassen","Weil dabei zu viele Kontextwechsel entstehen","Weil kurze Prozesse dabei immer bevorzugt werden","Weil der Scheduler dafür die Bedienzeit kennen muss"], a:0, e:"Ein Prozess läuft, bis er terminiert oder blockiert. Ein langer Rechenjob kann so die Antwortzeit aller anderen ruinieren."},
{t:"sch1", q:"Was passiert, wenn das Time Quantum bei Round Robin sehr klein ist?", o:["Es entsteht viel Overhead durch ständige Kontextwechsel","Round Robin verhält sich dann wie FCFS","Lange Prozesse verhungern vollständig","Kurze Prozesse werden stark benachteiligt"], a:0, e:"Jeder Wechsel kostet Zeit; bei winzigem Quantum geht ein großer Teil der CPU-Zeit fürs Umschalten drauf. Ideal: etwas größer als eine typische Interaktion."},
{t:"sch1", q:"Round Robin, q = 2. A (Ankunft 0, Dauer 3) und B (Ankunft 0, Dauer 2), A steht vorne. Wann ist A fertig?", o:["5","3","4","2"], a:0, e:"A 0–2, B 2–4 (B fertig), A 4–5 (A fertig). A braucht zwei Zeitscheiben."},
{t:"sch1", q:"Was ist HRRN (Highest Response Ratio Next)?", o:["Wählt den Prozess mit der höchsten Ratio (w + s) / s","Wählt den Prozess, der als Erster angekommen ist","Wählt den Prozess mit der kürzesten verbleibenden Rechenzeit","Wählt reihum jeden Prozess für eine feste Zeitscheibe"], a:0, e:"Response Ratio R = (w + s) / s. Kurze Prozesse haben schnell ein hohes R, aber auch lange Prozesse steigen mit der Wartezeit – so gibt es keine Starvation. HRRN ist non-preemptive."},
{t:"sch1", q:"Warum gibt es bei HRRN keine Starvation?", o:["Die Response Ratio wartender Prozesse steigt mit der Wartezeit immer weiter","Jeder Prozess bekommt eine feste Zeitscheibe zugeteilt","Lange Prozesse werden grundsätzlich zuerst ausgeführt","Neue Prozesse werden erst angenommen, wenn alle fertig sind"], a:0, e:"R = (w + s) / s wächst mit w. Irgendwann hat auch ein langer Prozess das höchste Verhältnis und wird gewählt (Aging-Effekt)."},
{t:"sch1", q:"HRRN: Prozess X wartet 6, Bedienzeit 2; Prozess Y wartet 8, Bedienzeit 8. Wer wird gewählt?", o:["X (Ratio 4)","Y (Ratio 2)","Y, weil er länger wartet","X, weil er kürzer ist – die Wartezeit zählt nicht"], a:0, e:"R(X) = (6 + 2) / 2 = 4. R(Y) = (8 + 8) / 8 = 2. Das höhere Verhältnis gewinnt: X."},
{t:"sch1", q:"Wie funktioniert Feedback-Scheduling (Multilevel Feedback)?", o:["Prozesse rutschen nach jeder Preemption in eine Queue mit niedrigerer Priorität","Prozesse steigen nach jeder Preemption in eine höhere Prioritätsqueue auf","Prozesse werden nach ihrer vorher geschätzten Bedienzeit sortiert","Jeder Prozess bleibt dauerhaft in der Queue, in die er anfangs kam"], a:0, e:"Neue Prozesse starten oben (RQ0). Wer seine Zeitscheibe verbraucht, wird herabgestuft. So werden kurze und I/O-lastige Prozesse bevorzugt, ohne die Bedienzeit kennen zu müssen."},
{t:"sch1", q:"Warum braucht Feedback-Scheduling keine Schätzung der Bedienzeit?", o:["Es lernt aus dem bisherigen Verhalten: wer viel rechnet, wird herabgestuft","Weil es alle Prozesse streng in Ankunftsreihenfolge bedient","Weil der Nutzer beim Start die Bedienzeit angeben muss","Weil jeder Prozess genau eine Zeitscheibe bekommt und dann endet"], a:0, e:"Statt die Zukunft zu schätzen (wie SPN), bestraft Feedback die bereits verbrauchte Zeit. Kurze Jobs sind fertig, bevor sie weit nach unten rutschen."},
{t:"sch1", q:"Welches Problem kann bei Feedback-Scheduling auftreten?", o:["Lange Prozesse können verhungern, wenn ständig neue kommen","Kurze Prozesse werden gegenüber langen benachteiligt","Die Bedienzeit jedes Prozesses muss genau bekannt sein","Prozesse können nie unterbrochen werden"], a:0, e:"Lange Prozesse landen in der untersten Queue; kommen ständig neue Prozesse oben an, werden sie kaum bedient. Abhilfe: längere Quanten in unteren Queues oder Aging."},
{t:"sch1", q:"Was ist Aging beim Priority Scheduling?", o:["Die Priorität wartender Prozesse wird mit der Zeit erhöht","Prozesse werden nach einer festen Lebensdauer beendet","Alte Prozesse bekommen automatisch die niedrigste Priorität","Die Zeitscheibe wird mit jedem Durchlauf kürzer"], a:0, e:"Aging verhindert Starvation: Ein Prozess mit niedriger Priorität steigt durch Warten auf und kommt irgendwann dran."},
{t:"sch1", q:"Warum kann reines Priority Scheduling zu Starvation führen?", o:["Solange Prozesse höherer Priorität bereit sind, kommen niedrige nie dran","Weil gleich priorisierte Prozesse sich gegenseitig blockieren","Weil hoch priorisierte Prozesse nach einer Zeitscheibe beendet werden","Weil die Priorität bei jeder Ausführung automatisch steigt"], a:0, e:"Innerhalb einer Stufe gilt FCFS, aber niedrigere Queues werden erst bedient, wenn alle höheren leer sind. Gegenmittel: Aging."},
// ---------- Erweiterung: Scheduling Advanced ----------
{t:"sch2", q:"Was ist Fine-grained Parallelism?", o:["Parallelität innerhalb eines Instruktionsstroms mit sehr häufiger Synchronisation","Unabhängige Prozesse, die sich praktisch nie synchronisieren","Parallelität zwischen Rechnern, die über ein Netz verbunden sind","Mehrere Programme, die nacheinander auf einer CPU laufen"], a:0, e:"Synchronisationsintervall < 20 Instruktionen – sehr eng gekoppelt, z. B. Parallelität auf Instruktionsebene. Je gröber, desto seltener wird synchronisiert."},
{t:"sch2", q:"Was ist Independent Parallelism?", o:["Unabhängige Prozesse ohne Synchronisation, z. B. mehrere Nutzer an einem System","Threads einer Anwendung, die sich sehr häufig synchronisieren","Instruktionen eines Befehlsstroms, die gleichzeitig ausgeführt werden","Ein Programm, das gleichzeitig auf mehreren Rechnern im Netz läuft"], a:0, e:"Kein explizites Synchronisieren nötig – typisch für Time-Sharing. Ein Multiprozessor bietet hier vor allem bessere Antwortzeiten."},
{t:"sch2", q:"Was ist ein loosely coupled (verteiltes) Multiprozessorsystem?", o:["Autonome Rechner mit eigenem Speicher, die über ein Netz kommunizieren","Prozessoren mit gemeinsamem Hauptspeicher unter einem einzigen OS","Ein Master-Prozessor mit spezialisierten I/O-Prozessoren","Ein Kern mit mehreren Hardware-Threads"], a:0, e:"Beispiel: Cluster. Jeder Knoten hat eigenen Speicher und eigenes OS; Kommunikation läuft über Nachrichten."},
{t:"sch2", q:"Was ist ein Vorteil der Master/Slave-Architektur?", o:["Konflikte sind einfach zu lösen, weil nur der Master Kernel-Code ausführt","Kein Prozessor kann zum Flaschenhals werden","Der Ausfall eines beliebigen Prozessors ist unproblematisch","Jeder Prozessor kann sich selbst Prozesse aus dem Pool nehmen"], a:0, e:"Der Master kontrolliert Speicher und I/O allein – keine Synchronisation zwischen Kernel-Instanzen nötig. Nachteil: Single Point of Failure und Flaschenhals."},
{t:"sch2", q:"Was ist Load Sharing beim Thread-Scheduling?", o:["Alle bereiten Threads liegen in einer globalen Queue; freie Prozessoren holen sich den nächsten","Jeder Thread ist fest einem bestimmten Prozessor zugeordnet","Alle Threads eines Prozesses starten gleichzeitig auf mehreren CPUs","Ein Master-Prozessor verteilt die Threads an spezialisierte Prozessoren"], a:0, e:"Einfachste Form, Last gleichmäßig verteilt, kein zentraler Scheduler. Nachteile: Mutual Exclusion auf der Queue, Threads wechseln oft den Prozessor (Cache), Threads eines Prozesses laufen selten gemeinsam."},
{t:"sch2", q:"Was ist Dedicated Processor Assignment?", o:["Jeder Thread einer Anwendung bekommt für ihre Laufzeit einen eigenen Prozessor","Alle Threads teilen sich eine globale Ready-Queue","Threads wandern ständig zwischen den Prozessoren hin und her","Die Anzahl der Threads wird während der Laufzeit vom OS angepasst"], a:0, e:"Extremform von Gang Scheduling: keine Prozesswechsel, keine Wartezeiten bei der Synchronisation. Nachteil: Blockiert ein Thread, bleibt sein Prozessor ungenutzt."},
{t:"sch2", q:"Was ist Dynamic Scheduling bei Multiprozessoren?", o:["Die Anzahl der Threads eines Prozesses kann sich zur Laufzeit ändern","Jeder Thread bekommt dauerhaft einen festen Prozessor","Alle Threads werden nur einmal beim Start verteilt","Threads werden nach einer festen Tabelle vor Laufzeit eingeplant"], a:0, e:"OS und Anwendung arbeiten zusammen: Die Anwendung passt die Thread-Anzahl an die verfügbaren Prozessoren an."},
{t:"sch2", q:"Warum ist es ungünstig, wenn ein Thread bei jedem Wechsel auf einem anderen Prozessor läuft?", o:["Die Daten in dessen Cache gehen verloren und müssen neu geladen werden","Der Thread muss dann jedes Mal neu erzeugt werden","Auf einem anderen Prozessor gilt eine andere Page Table","Prozessoren können nur Threads eines einzigen Prozesses ausführen"], a:0, e:"Cache-Affinität: Ein Thread, der wieder auf demselben Kern läuft, findet seine Daten oft noch im Cache. Das ist ein Nachteil von Load Sharing."},
{t:"sch2", q:"Was unterscheidet periodische von aperiodischen Echtzeit-Tasks?", o:["Periodische kehren in festen Abständen wieder, aperiodische treten unvorhersehbar auf","Periodische haben harte Deadlines, aperiodische haben gar keine","Periodische laufen im Kernel, aperiodische im User Mode","Periodische dürfen unterbrochen werden, aperiodische nicht"], a:0, e:"Beispiel periodisch: Sensor alle 10 ms auslesen. Aperiodisch: Reaktion auf einen Alarm. Beide können harte oder weiche Deadlines haben."},
{t:"sch2", q:"Was macht Static table-driven Scheduling?", o:["Es berechnet vor der Laufzeit einen festen Plan, wann welcher Task läuft","Es prüft bei jeder Ankunft eines Tasks, ob alle Deadlines haltbar sind","Es versucht alle Deadlines zu halten, ohne vorher etwas zu prüfen","Es vergibt feste Prioritäten und lässt dann einen normalen Scheduler arbeiten"], a:0, e:"Geeignet für periodische Tasks mit bekannten Anforderungen. Nachteil: unflexibel – jede Änderung erfordert einen neuen Plan."},
{t:"sch2", q:"Was ist Earliest Deadline First (EDF)?", o:["Es läuft immer der bereite Task mit der frühesten Deadline","Es läuft immer der Task mit der kürzesten Rechenzeit","Es läuft immer der Task, der am längsten wartet","Es läuft immer der Task mit der kürzesten Periode"], a:0, e:"EDF passt die Reihenfolge dynamisch an die Deadlines an – im Folienbeispiel hält es als einziges Verfahren alle Deadlines der Tasks A und B ein."},
{t:"sch2", q:"Was ist Rate Monotonic Scheduling (RMS)?", o:["Statische Prioritäten: je kürzer die Periode eines Tasks, desto höher seine Priorität","Dynamische Prioritäten: die früheste Deadline bekommt die höchste Priorität","Prioritäten nach Rechenzeit: der kürzeste Task bekommt die höchste Priorität","Alle periodischen Tasks bekommen die gleiche Priorität und laufen reihum"], a:0, e:"Häufige Tasks (hohe Rate) sind wichtiger. RMS ist einfach und vorhersagbar, kann aber nicht ganz so viel Auslastung garantieren wie EDF."},
{t:"sch2", q:"Was ist Priority Inversion?", o:["Ein hoch priorisierter Task wartet auf eine Ressource, die ein niedrig priorisierter hält","Ein niedrig priorisierter Task bekommt nie die CPU, weil höhere immer bereit sind","Zwei Tasks warten zyklisch auf Ressourcen des jeweils anderen","Der Scheduler vertauscht versehentlich die Prioritäten zweier Tasks"], a:0, e:"Gefährlich wird es, wenn ein mittlerer Task den niedrigen verdrängt: Dann wartet der hohe Task indirekt auf den mittleren (unbounded priority inversion). Bekanntes Beispiel: Mars Pathfinder."},
{t:"sch2", q:"Wie funktioniert Priority Inheritance?", o:["Der Task, der die Ressource hält, erbt vorübergehend die höhere Priorität des Wartenden","Der wartende Task gibt seine Priorität dauerhaft an alle anderen ab","Jede Ressource bekommt beim Erzeugen eine feste Höchstpriorität","Alle Tasks erhalten beim Sperren einer Ressource dieselbe Priorität"], a:0, e:"So kann ein mittlerer Task den Ressourcenhalter nicht mehr verdrängen; nach der Freigabe fällt die Priorität zurück. Alternative: Priority Ceiling."},
{t:"sch2", q:"Warum ist ungebundene Priority Inversion für Echtzeitsysteme gefährlich?", o:["Deadlines werden unvorhersehbar und können platzen","Weil dabei immer ein Deadlock zwischen allen Tasks entsteht","Weil der niedrig priorisierte Task dadurch abstürzt","Weil die CPU-Auslastung dadurch auf null fällt"], a:0, e:"Echtzeit braucht Determinismus. Kann ein beliebiger mittlerer Task den hohen Task indirekt beliebig lange aufhalten, ist keine Zeitgarantie mehr möglich."},
// ---------- Erweiterung: Synchronisation ----------
{t:"sync", q:"Was bedeutet die Deadlock-Bedingung „Hold-and-Wait“?", o:["Ein Prozess hält Ressourcen und wartet gleichzeitig auf weitere","Ein Prozess wartet, bis eine Ressource ihm weggenommen wird","Ein Prozess hält eine Ressource und gibt sie sofort wieder frei","Mehrere Prozesse warten gemeinsam in einer FIFO-Queue"], a:0, e:"Zusammen mit Mutual Exclusion, No Preemption und Circular Wait führt Hold-and-Wait zum Deadlock. Prevention: alle Ressourcen auf einmal anfordern."},
{t:"sync", q:"Wie verhindert man einen Deadlock durch Ausschluss von Circular Wait?", o:["Alle Ressourcen werden durchnummeriert und nur in aufsteigender Reihenfolge angefordert","Jeder Prozess darf zu einem Zeitpunkt immer nur eine Ressource halten","Das OS prüft regelmäßig den Ressourcengraphen und bricht Prozesse ab","Ressourcen werden einem Prozess bei Bedarf gewaltsam entzogen"], a:0, e:"Mit einer globalen Ordnung kann kein Zyklus entstehen. Das ist Deadlock Prevention."},
{t:"sync", q:"Was macht Deadlock Detection?", o:["Anfragen werden gewährt; periodisch wird geprüft, ob ein Deadlock entstanden ist","Jede Anfrage wird abgelehnt, die zu einem unsicheren Zustand führen könnte","Eine der vier Deadlock-Bedingungen wird grundsätzlich ausgeschlossen","Prozesse müssen beim Start alle Ressourcen auf einmal anfordern"], a:0, e:"Nach der Erkennung folgt Recovery: Prozesse abbrechen, Ressourcen entziehen oder auf einen Checkpoint zurücksetzen."},
{t:"sync", q:"Was ist ein sicherer Zustand (Safe State) bei Deadlock Avoidance?", o:["Es gibt eine Reihenfolge, in der alle fertig werden können","Kein Prozess hält im Moment irgendeine Ressource","Alle Prozesse sind gerade im Zustand Running","Es sind mehr freie Ressourcen vorhanden als Prozesse"], a:0, e:"Der Banker's Algorithm gewährt eine Anfrage nur, wenn der Folgezustand sicher ist. Unsicher heißt nicht zwingend Deadlock – aber er ist möglich."},
{t:"sync", q:"Was unterscheidet eine named von einer unnamed Pipe?", o:["Named Pipes haben einen Namen im Dateisystem und verbinden auch fremde Prozesse","Named Pipes sind LIFO, unnamed Pipes sind FIFO","Unnamed Pipes funktionieren zwischen beliebigen Prozessen im Netz","Named Pipes übertragen Nachrichten mit Typ, unnamed Pipes Bytes"], a:0, e:"Unnamed Pipes gibt es nur zwischen verwandten Prozessen (z. B. Eltern/Kind nach fork, wie bei ls | grep). Named Pipes (FIFOs) stehen im Dateisystem und können von beliebigen Prozessen geöffnet werden."},
{t:"sync", q:"Warum müssen Prozesse bei Shared Memory selbst für Synchronisation sorgen?", o:["Der Kernel ist bei den einzelnen Zugriffen nicht beteiligt und schützt nichts","Shared Memory wird bei jedem Zugriff vom Kernel gesperrt","Weil Shared Memory nur gelesen, aber nicht beschrieben werden kann","Weil der Speicher nach jedem Zugriff automatisch gelöscht wird"], a:0, e:"Gerade das macht Shared Memory schnell: Nach dem Einrichten greifen die Prozesse direkt zu. Gleichzeitige Schreibzugriffe brauchen daher z. B. Semaphoren."},
{t:"sync", q:"Was ist eine zählende Semaphore (Counting Semaphore)?", o:["Ein Zähler, der angibt, wie viele Prozesse noch eine Ressource bekommen können","Ein Lock, den nur der sperrende Thread wieder freigeben darf","Ein Zähler für die Anzahl bereits beendeter Prozesse","Eine Queue, in der Nachrichten nach Typ abgelegt werden"], a:0, e:"wait/P: Zähler − 1; wird er negativ, blockiert der Prozess. signal/V: Zähler + 1; ein Wartender wird geweckt. Mit Startwert N dürfen N Prozesse gleichzeitig hinein."},
{t:"sync", q:"Was passiert bei semWait (P), wenn der Semaphorenwert danach negativ ist?", o:["Der Prozess wird blockiert und in die Warteschlange der Semaphore gestellt","Der Prozess darf trotzdem in den kritischen Abschnitt","Der Wert wird auf null zurückgesetzt und der Prozess läuft weiter","Der Prozess wird beendet, weil die Ressource erschöpft ist"], a:0, e:"Der negative Wert gibt die Anzahl der Wartenden an. Erst semSignal (V) eines anderen Prozesses weckt einen von ihnen."},
{t:"sync", q:"Wie löst man das Producer-Consumer-Problem mit Semaphoren?", o:["Je eine Semaphore für freie und belegte Plätze, plus ein Mutex für den Puffer","Eine einzige Semaphore, die der Producer setzt und nie freigibt","Ein Spinlock, auf den der Consumer in einer Schleife wartet","Gar nicht – das Problem braucht zwingend Shared Memory ohne Sync"], a:0, e:"empty (Start N) blockiert den Producer bei vollem Puffer, full (Start 0) den Consumer bei leerem. Der Mutex schützt den Puffer selbst vor gleichzeitigen Zugriffen."},
{t:"sync", q:"Was ist ein kritischer Abschnitt (Critical Section)?", o:["Code, der gemeinsame Daten nutzt und exklusiv laufen muss","Ein Codeteil, der im Kernel Mode ausgeführt werden muss","Ein Codeteil, der bei einem Fehler das Programm beendet","Ein Codeteil, der besonders viel Rechenzeit benötigt"], a:0, e:"Damit keine Race Condition entsteht, darf immer nur ein Prozess/Thread gleichzeitig im kritischen Abschnitt sein (Mutual Exclusion), z. B. bei i++ auf einer geteilten Variable."},
{t:"sync", q:"Was bedeutet Mutual Exclusion?", o:["Höchstens ein Prozess darf gleichzeitig im kritischen Abschnitt sein","Zwei Prozesse schließen sich gegenseitig vom Scheduling aus","Ein Prozess darf nie mehr als eine Ressource gleichzeitig nutzen","Prozesse dürfen keinen gemeinsamen Speicher benutzen"], a:0, e:"Wechselseitiger Ausschluss verhindert Race Conditions. Er ist zugleich eine der vier Deadlock-Bedingungen."},
{t:"sync", q:"Was ist Starvation (Verhungern) im Kontext der Synchronisation?", o:["Ein Prozess wird immer wieder übergangen und erhält die Ressource nie","Alle Prozesse warten zyklisch aufeinander und keiner kommt weiter","Das Ergebnis hängt von der Reihenfolge der Zugriffe ab","Ein Prozess wartet aktiv in einer Schleife auf einen Lock"], a:0, e:"Anders als beim Deadlock läuft das System weiter – nur ein bestimmter Prozess kommt nie dran. Gegenmittel: faire Warteschlangen, Aging."},
{t:"sync", q:"Was ist der Unterschied zwischen Mutex und binärer Semaphore?", o:["Beim Mutex darf nur der Besitzer entsperren, bei der Semaphore jeder Prozess","Beim Mutex darf jeder entsperren, bei der Semaphore nur der Besitzer","Ein Mutex lässt N Threads gleichzeitig hinein, die Semaphore nur einen","Es gibt überhaupt keinen Unterschied zwischen beiden"], a:0, e:"Beide erlauben nur einen gleichzeitig (Werte 0/1). Der Mutex hat aber einen Besitzer – das passt für gegenseitigen Ausschluss; Semaphoren eignen sich auch zur Signalisierung zwischen Prozessen."},
{t:"sync", q:"Warum verwendet der Kernel atomare Integer-Operationen etwa für Zähler?", o:["Sie sind unteilbar und brauchen daher keinen zusätzlichen Lock","Sie laufen schneller, weil sie den Cache umgehen","Sie dürfen nur vom Scheduler aufgerufen werden","Sie verhindern, dass der Zähler jemals negativ wird"], a:0, e:"Eine atomare Operation (z. B. atomic_inc) kann nicht unterbrochen werden und nicht mit anderen kollidieren – billiger als ein Lock für einen einzelnen Zähler."},
{t:"sync", q:"Welche Ursache hat ein „lost update“ bei i++ in zwei Threads?", o:["Beide lesen denselben alten Wert, bevor einer den neuen zurückschreibt","Der Compiler optimiert die zweite Erhöhung einfach weg","Der zweite Thread wird vom Kernel blockiert und vergessen","Die Variable liegt in zwei verschiedenen Adressräumen"], a:0, e:"Ablauf: T1 liest 5, T2 liest 5, T1 schreibt 6, T2 schreibt 6 – eine Erhöhung ist verloren. Abhilfe: atomare Operation oder Lock."},
// ---------- Erweiterung: Memory ----------
{t:"mem", q:"Was bedeutet die Memory-Management-Anforderung „Sharing“?", o:["Mehrere Prozesse dürfen kontrolliert auf denselben Speicher zugreifen","Ein Prozess darf nach dem Swapping woanders im RAM landen","Ein Prozess darf nicht auf fremde Speicherbereiche zugreifen","Der Speicher wird gleichmäßig auf alle Prozesse aufgeteilt"], a:0, e:"Beispiel: Mehrere Prozesse desselben Programms teilen sich den Code, oder Prozesse nutzen eine gemeinsame Bibliothek – ohne den Schutz aufzugeben."},
{t:"mem", q:"Warum kann Speicherschutz (Protection) nicht nur zur Compile-Zeit geprüft werden?", o:["Adressen entstehen oft erst zur Laufzeit, z. B. durch Pointer und Relocation","Weil Compiler grundsätzlich keine Adressen berechnen können","Weil der Kernel den Programmcode vor dem Start nicht lesen darf","Weil sich die Größe des RAM während der Laufzeit ändert"], a:0, e:"Wo ein Prozess liegt und welche Adressen er berechnet, steht erst beim Ausführen fest. Deshalb prüft die Hardware (MMU) jeden Zugriff."},
{t:"mem", q:"Was ist eine logische Adresse?", o:["Eine Adresse, die unabhängig davon ist, wo der Prozess gerade im RAM liegt","Die tatsächliche Position eines Bytes im physischen Hauptspeicher","Die Nummer eines Blocks auf der Festplatte","Die Adresse eines Geräts auf dem Systembus"], a:0, e:"Das Programm arbeitet mit logischen Adressen; vor dem Zugriff werden sie (z. B. von der MMU) in physische Adressen übersetzt. Relative Adressen sind ein Spezialfall."},
{t:"mem", q:"Was ist Fixed Partitioning?", o:["Der Speicher ist beim Systemstart in Partitionen fester Größe eingeteilt","Jeder Prozess bekommt genau so viel Speicher, wie er braucht","Prozesse werden in Seiten gleicher Größe zerlegt","Der Speicher wird in Zweierpotenzen geteilt und wieder vereinigt"], a:0, e:"Einfach, aber: Ein kleiner Prozess belegt eine ganze Partition (interne Fragmentierung), und die Anzahl aktiver Prozesse ist begrenzt."},
{t:"mem", q:"Was ist Compaction?", o:["Prozesse werden im Speicher verschoben, damit die freien Lücken zusammenhängen","Seiten eines Prozesses werden komprimiert auf die Festplatte geschrieben","Mehrere kleine Prozesse werden zu einem großen Prozess vereinigt","Der Speicher wird in Blöcke von Zweierpotenzgröße zerlegt"], a:0, e:"Gegenmittel gegen externe Fragmentierung bei Dynamic Partitioning – aber zeitaufwendig und nur mit dynamischer Relocation möglich."},
{t:"mem", q:"Was macht die Placement-Strategie First-fit?", o:["Sie nimmt vom Anfang aus den ersten freien Block, der groß genug ist","Sie nimmt den Block, der der Anfrage größenmäßig am nächsten kommt","Sie sucht ab der letzten Platzierung den nächsten passenden Block","Sie nimmt immer den größten verfügbaren freien Block"], a:0, e:"First-fit ist einfach und meist schnell und schneidet in der Praxis oft am besten ab."},
{t:"mem", q:"Warum erzeugt Best-fit oft viele sehr kleine, unbrauchbare Lücken?", o:["Der Rest nach dem bestpassenden Block ist meist winzig","Weil Best-fit immer den größten Block zerteilt","Weil Best-fit Blöcke absichtlich halbiert","Weil Best-fit freie Blöcke nie wieder vereinigt"], a:0, e:"Passt ein Block fast genau, bleibt ein Mini-Rest übrig, der für fast nichts reicht. Deshalb ist Best-fit trotz des Namens oft nicht die beste Strategie."},
{t:"mem", q:"Was passiert im Buddy System, wenn ein Block freigegeben wird?", o:["Ist sein Buddy frei, werden beide zu einem Block vereinigt","Der Block wird sofort in vier gleich große Teile zerlegt","Der Block bleibt reserviert, bis das System neu startet","Der Block wird an den Anfang des Speichers verschoben"], a:0, e:"Zwei gleich große Nachbarn, die durch Teilung entstanden sind, sind Buddies. Sind beide frei, verschmelzen sie – das kann sich über mehrere Ebenen fortsetzen."},
{t:"mem", q:"Was ist der Unterschied zwischen Page und Page Frame?", o:["Page: Block im logischen Adressraum; Frame: gleich großer Block im RAM","Page: Block im RAM; Frame: gleich großer Block im logischen Adressraum","Page: Block auf der Platte; Frame: Block im Cache","Page und Frame haben grundsätzlich unterschiedliche Größen"], a:0, e:"Die Page Table bildet jede Page eines Prozesses auf einen Frame ab. Beide sind gleich groß (z. B. 4 KB), damit der Offset unverändert bleibt."},
{t:"mem", q:"Wie setzt sich eine Adresse bei Segmentation zusammen?", o:["Aus Segmentnummer und Offset innerhalb des Segments","Aus Seitennummer und Rahmennummer","Aus Blocknummer und Plattennummer","Aus Prozessnummer und physischer Adresse"], a:0, e:"Die Segmenttabelle liefert Startadresse und Länge des Segments; der Offset wird dazuaddiert und gegen die Länge geprüft."},
{t:"mem", q:"Warum ist Segmentation für Programmierer oft sichtbar und nützlich?", o:["Segmente entsprechen logischen Einheiten wie Code, Daten oder Stack","Segmente haben alle die gleiche Größe und sind leicht zu zählen","Segmente werden vom Compiler komplett vor dem Programmierer versteckt","Segmente verhindern jede Form von Fragmentierung"], a:0, e:"Das erleichtert Schutz und Sharing pro logischer Einheit (z. B. Code nur lesbar, Bibliothek geteilt). Nachteil: externe Fragmentierung, da Segmente variabel groß sind."},
{t:"mem", q:"Was ist der TLB (Translation Lookaside Buffer)?", o:["Ein schneller Cache für kürzlich benutzte Page-Table-Einträge","Ein Puffer, in dem ausgelagerte Seiten auf der Platte liegen","Die Liste aller freien Page Frames im Hauptspeicher","Ein Register, das die Startadresse der Page Table enthält"], a:0, e:"Ohne TLB bräuchte jeder Speicherzugriff zusätzlich einen (bei mehrstufigen Tabellen mehrere) Zugriffe auf die Page Table. Ein TLB-Hit spart diese Zugriffe."},
{t:"mem", q:"Warum lohnt sich der TLB trotz seiner geringen Größe?", o:["Wegen der Lokalität treffen die meisten Zugriffe dieselben wenigen Seiten","Weil er die komplette Page Table jedes Prozesses enthält","Weil er Page Faults vollständig verhindert","Weil er Daten schneller als jedes andere Register überträgt"], a:0, e:"Programme greifen meist auf wenige Seiten zu (Lokalität). Deshalb reichen einige Dutzend bis Tausend Einträge für eine sehr hohe Trefferrate."},
{t:"mem", q:"Wozu dient das Modify-Bit (Dirty Bit) in einem Page-Table-Eintrag?", o:["Es zeigt, ob die Seite geändert wurde (zurückschreiben nötig)","Es zeigt, ob die Seite gerade im Hauptspeicher liegt","Es zeigt, ob die Seite kürzlich gelesen wurde","Es zeigt, ob die Seite von mehreren Prozessen geteilt wird"], a:0, e:"Unveränderte Seiten können einfach verworfen werden (die Kopie auf der Platte ist noch aktuell); geänderte müssen erst geschrieben werden."},
{t:"mem", q:"Was macht der Optimal-Algorithmus (OPT) bei der Seitenersetzung?", o:["Er verdrängt die Seite, deren nächste Nutzung am weitesten in der Zukunft liegt","Er verdrängt die Seite, die am längsten im Speicher liegt","Er verdrängt die Seite, die am längsten nicht benutzt wurde","Er verdrängt eine zufällig gewählte Seite"], a:0, e:"OPT ist beweisbar optimal, braucht aber Wissen über die Zukunft – nicht umsetzbar, dient nur als Vergleichsmaßstab."},
{t:"mem", q:"Was ist der Unterschied zwischen LRU und FIFO bei der Seitenersetzung?", o:["LRU verdrängt die am längsten nicht benutzte, FIFO die am längsten geladene Seite","LRU verdrängt die am längsten geladene, FIFO die am längsten nicht benutzte Seite","LRU verdrängt zufällig, FIFO nach fester Reihenfolge","Es gibt keinen Unterschied"], a:0, e:"FIFO kann eine häufig benutzte, aber alte Seite verdrängen. LRU berücksichtigt die Nutzung, ist aber teuer umzusetzen – Clock/Second Chance nähern LRU billig an."},
{t:"mem", q:"Wie funktioniert der Clock-Algorithmus?", o:["Ein Zeiger läuft im Kreis; Seiten mit Use-Bit 1 bekommen 0, die erste mit 0 wird verdrängt","Ein Zeiger läuft im Kreis und verdrängt jede Seite, auf die er zeigt","Jede Seite bekommt einen Zeitstempel; die älteste wird verdrängt","Die Seiten werden nach Größe sortiert und die größte wird verdrängt"], a:0, e:"Clock ist eine effiziente Umsetzung von Second Chance: Kürzlich benutzte Seiten werden übersprungen (Bit gelöscht), bis eine ungenutzte gefunden ist."},
// ---------- Erweiterung: File Systems ----------
{t:"fs", q:"Was ist ein i-node?", o:["Eine Datenstruktur mit allen Metadaten und Blockadressen einer Datei","Ein Verzeichniseintrag, der den Namen einer Datei speichert","Ein Datenblock, der den eigentlichen Dateiinhalt enthält","Eine Tabelle, die alle freien Blöcke der Platte verzeichnet"], a:0, e:"Der i-node enthält Rechte, Owner, Größe, Zeitstempel, Link Count und Blockadressen – aber nicht den Namen. Verzeichnisse ordnen Namen i-node-Nummern zu."},
{t:"fs", q:"Warum braucht ein i-node Indirect Blocks?", o:["Damit auch sehr große Dateien mit einem kleinen i-node adressiert werden können","Damit kleine Dateien schneller gelesen werden können","Damit mehrere Dateien sich einen Datenblock teilen können","Damit der Dateiname direkt im i-node gespeichert werden kann"], a:0, e:"Der i-node hat nur wenige direkte Blockadressen. Ein Single Indirect Block enthält weitere Adressen, Double und Triple Indirect noch mehr Ebenen – kleine Dateien kommen ohne Umweg aus."},
{t:"fs", q:"Was speichert der Link Count im i-node?", o:["Wie viele Verzeichniseinträge (Hard Links) auf diesen i-node zeigen","Wie viele Prozesse die Datei gerade geöffnet haben","Wie viele symbolische Links es auf die Datei gibt","Wie viele Datenblöcke die Datei belegt"], a:0, e:"Erst wenn der Link Count auf 0 fällt (und niemand die Datei offen hat), werden i-node und Blöcke freigegeben."},
{t:"fs", q:"Was passiert mit einem symbolischen Link, wenn die Zieldatei gelöscht wird?", o:["Er bleibt bestehen, zeigt aber ins Leere (dangling link)","Er wird automatisch mitgelöscht","Er wird automatisch zur Kopie der Datei","Die Datei bleibt bestehen, solange der Symlink existiert"], a:0, e:"Ein Symlink speichert nur den Pfad. Anders beim Hard Link: Dort lebt die Datei weiter, solange der Link Count > 0 ist."},
{t:"fs", q:"Was ist ein Disk Quota?", o:["Eine Obergrenze für Plattenplatz bzw. Dateianzahl pro Benutzer","Der Anteil der Platte, den das OS selbst reserviert","Die maximale Größe einer einzelnen Datei im Dateisystem","Die Anzahl der Partitionen, die eine Platte haben darf"], a:0, e:"Quotas verhindern, dass einzelne Nutzer die Platte füllen. Soft-Limit: mit Warnungen überschreitbar; Hard-Limit: nie."},
{t:"fs", q:"Was ist die FAT (File Allocation Table)?", o:["Eine Tabelle, die für jeden Block den Folgeblock der Datei enthält","Eine Tabelle, die jedem Dateinamen seinen i-node zuordnet","Eine Liste aller Benutzer mit ihren Zugriffsrechten","Ein Index über die Inhalte aller Dateien"], a:0, e:"Linked-List-Belegung, aber die Zeiger stehen in einer Tabelle statt in den Blöcken. Liegt die FAT im RAM, ist wahlfreier Zugriff schnell – bei großen Platten wird die Tabelle aber groß."},
{t:"fs", q:"Was ist Linked-List-Belegung von Plattenblöcken?", o:["Jeder Block einer Datei enthält einen Zeiger auf den nächsten Block","Alle Blöcke einer Datei liegen direkt hintereinander","Ein Indexblock enthält die Adressen aller Datenblöcke","Blöcke werden per Hash-Funktion auf die Platte verteilt"], a:0, e:"Vorteil: keine externe Fragmentierung. Nachteil: Wahlfreier Zugriff ist langsam (alle Vorgänger lesen) und der Zeiger kostet Platz in jedem Block."},
{t:"fs", q:"Was ist ein Vorteil der zusammenhängenden (contiguous) Belegung?", o:["Sehr schnelles Lesen, weil die Blöcke direkt hintereinander liegen","Keine Lücken beim Löschen von Dateien","Dateien können beliebig wachsen, ohne verschoben zu werden","Kein Verwaltungsaufwand für Zeiger oder Tabellen nötig, auch beim Wachsen"], a:0, e:"Man braucht nur Startblock und Länge. Ideal für Medien, die einmal geschrieben werden (z. B. CD/DVD). Nachteil: externe Fragmentierung und schwieriges Wachsen."},
{t:"fs", q:"Was ist indizierte Belegung von Plattenblöcken?", o:["Ein Indexblock bzw. i-node enthält die Adressen aller Datenblöcke","Jeder Block enthält einen Zeiger auf den nächsten","Alle Blöcke einer Datei müssen hintereinander liegen","Die Datei wird in einen einzigen großen Block geschrieben"], a:0, e:"Schneller wahlfreier Zugriff und keine externe Fragmentierung. UNIX nutzt dies mit dem i-node (direkte + indirekte Blockadressen)."},
{t:"fs", q:"Was ist ein Verzeichnis (Directory)?", o:["Eine spezielle Datei, die Namen auf Dateien bzw. i-nodes abbildet","Ein Bereich der Platte, der nur für Systemdateien reserviert ist","Eine Kopie aller Dateien, die zum Backup genutzt wird","Ein Prozess, der den Zugriff auf Dateien überwacht"], a:0, e:"Verzeichnisse ordnen Dateien und ermöglichen Pfadnamen. Unter UNIX enthält ein Verzeichniseintrag Name und i-node-Nummer."},
{t:"fs", q:"Was ist der Vorteil eines hierarchischen (baumförmigen) Verzeichnissystems?", o:["Dateien lassen sich logisch gruppieren und gleiche Namen sind in verschiedenen Ordnern möglich","Jede Datei kann nur einmal im ganzen System existieren","Alle Dateien liegen in einem einzigen Verzeichnis und sind schnell auffindbar","Zugriffsrechte sind dadurch nicht mehr nötig"], a:0, e:"Bei einem einzigen flachen Verzeichnis gäbe es Namenskonflikte zwischen Nutzern und keine Ordnung. Der Baum erlaubt z. B. /home/a/notes und /home/b/notes."},
{t:"fs", q:"Was ist das Arbeitsverzeichnis (Working Directory)?", o:["Das Verzeichnis, von dem aus relative Pfade eines Prozesses aufgelöst werden","Das Verzeichnis, in dem temporäre Dateien gespeichert werden","Das Verzeichnis, in dem das Betriebssystem installiert ist","Das Verzeichnis, das beim Booten zuerst gemountet wird"], a:0, e:"Jeder Prozess hat ein aktuelles Verzeichnis (cd ändert es in der Shell). Relative Pfade wie notes.txt beziehen sich darauf, absolute beginnen bei /."},
{t:"fs", q:"Welche Rolle spielen die Schichten Logical I/O und Access Method im Dateisystem?", o:["Logical I/O arbeitet mit Records, die Access Method mit der Dateiorganisation","Logical I/O steuert Geräteregister, die Access Method verteilt Plattenblöcke","Logical I/O schreibt Blöcke, die Access Method verwaltet die Interrupts","Beide Schichten liegen direkt über der Hardware"], a:0, e:"Von unten: Device Driver → Basic File System (Blöcke) → Basic I/O Supervisor → Logical I/O (Records) → Access Method (Pile, Sequential, Indexed …) → User Program."},
{t:"fs", q:"Was ist der Master Boot Record (MBR)?", o:["Der erste Sektor der Platte mit Bootcode und Partitionstabelle","Die letzte Partition der Platte, in der das Backup liegt","Eine Datei, die alle Benutzerkonten des Systems enthält","Der i-node des Root-Verzeichnisses"], a:0, e:"Das BIOS lädt den MBR (Sektor 0) und führt seinen Bootcode aus. Die alte MBR-Partitionstabelle ist auf 4 primäre Partitionen und 2 TB begrenzt – GPT ersetzt sie."},
{t:"fs", q:"Warum ersetzt GPT zunehmend den klassischen MBR?", o:["Es erlaubt größere Platten, mehr Partitionen und hat eine Backup-Kopie","Es ist die einzige Methode, um überhaupt mehrere Partitionen anzulegen","Es speichert die Dateien direkt in der Partitionstabelle","Es macht ein Dateisystem auf den Partitionen überflüssig"], a:0, e:"GPT (mit UEFI) unterstützt sehr große Platten und viele Partitionen; die Backup-GPT am Ende schützt vor Beschädigung. Block 0 bleibt für einen Schutz-MBR reserviert."},
{t:"fs", q:"Welche Android-Partition wird read-write gemountet und enthält App-Daten?", o:["/data","/system","/boot","/vendor"], a:0, e:"/data, /cache und /mnt/sdcard sind rw. /system ist ro, damit Systemdateien geschützt bleiben."},
{t:"fs", q:"Was ist eine Bitmap bei der Freispeicherverwaltung?", o:["Ein Bit pro Block, das angibt, ob der Block frei oder belegt ist","Ein Bild der Platte, das defekte Sektoren markiert","Eine Liste aller Dateien, sortiert nach Größe","Eine Tabelle, die jedem Block seinen Folgeblock zuordnet"], a:0, e:"Kompakt (1 Bit pro Block) und man findet leicht zusammenhängende freie Bereiche. Bei sehr großen Platten wird die Bitmap aber selbst groß."},
{t:"fs", q:"Was ist eine Free List bei der Freispeicherverwaltung?", o:["Eine verkettete Liste der freien Plattenblöcke","Eine Liste aller Dateien, die gelöscht werden dürfen","Eine Liste aller Benutzer ohne Disk Quota","Eine Liste der Prozesse, die auf einen Block warten"], a:0, e:"Freie Blöcke werden verkettet (oder Blöcke voller Adressen freier Blöcke). Braucht kaum Platz, wenn die Platte voll ist, aber zusammenhängende Bereiche sind schwer zu finden."},
{t:"fs", q:"Warum muss das Dateisystem freie Blöcke überhaupt verwalten?", o:["Damit beim Schreiben schnell ein freier Block gefunden wird und keiner doppelt vergeben wird","Damit gelöschte Dateien jederzeit vollständig wiederhergestellt werden können","Damit die Platte beim Booten schneller erkannt wird","Damit Dateien automatisch komprimiert werden"], a:0, e:"Ohne Buchführung müsste man die ganze Platte durchsuchen – oder riskiert, belegte Blöcke zu überschreiben. Verfahren: Bitmap oder Free List."},
// ---------- Erweiterung: I/O & RAID ----------
{t:"io", q:"Was ist Interrupt-driven I/O?", o:["Die CPU startet die I/O, arbeitet weiter und wird beim Abschluss unterbrochen","Die CPU fragt das Gerät in einer Schleife ab, bis es fertig ist","Ein eigenes Modul überträgt ganze Blöcke ohne die CPU","Das Gerät schreibt die Daten direkt in die CPU-Register"], a:0, e:"Kein Busy Waiting mehr – aber die CPU muss weiterhin jedes Wort selbst übertragen. Für große Datenmengen nutzt man daher DMA."},
{t:"io", q:"Warum lohnt sich DMA besonders bei großen Datenmengen?", o:["Die CPU wird nur am Anfang und Ende beteiligt, nicht bei jedem Wort","DMA überträgt Daten ohne Nutzung des Systembusses","DMA macht Interrupts komplett überflüssig","DMA verschlüsselt die Daten während der Übertragung"], a:0, e:"Bei Interrupt-driven I/O gäbe es pro Wort Arbeit für die CPU. Mit DMA gibt es nur einen Interrupt am Ende des Blocks. Das DMA-Modul nutzt den Bus, wenn die CPU ihn nicht braucht (Cycle Stealing)."},
{t:"io", q:"Was bedeutet „Cycle Stealing“ bei DMA?", o:["Das DMA-Modul nutzt den Bus und hält die CPU dafür kurz an","Die CPU unterbricht das DMA-Modul in jedem Taktzyklus","Ein Prozess nimmt einem anderen seine Zeitscheibe weg","Der Cache übernimmt Taktzyklen des Hauptspeichers"], a:0, e:"Die CPU wird nicht unterbrochen (kein Kontextwechsel), sondern pausiert nur für einen Buszyklus. Dadurch wird sie etwas langsamer, aber viel weniger belastet als ohne DMA."},
{t:"io", q:"Was ist ein stream-orientiertes Gerät?", o:["Ein Gerät, das Daten als Bytestrom ohne Blockstruktur überträgt","Ein Gerät, das Daten in Blöcken fester Größe speichert","Ein Gerät, das nur Videoströme übertragen kann","Ein Gerät, das ausschließlich über das Netz angebunden ist"], a:0, e:"Beispiele: Terminal, Drucker, Maus, Kommunikationsports. Blockorientiert sind z. B. Platten und USB-Sticks."},
{t:"io", q:"Wozu gehören Bildschirm, Tastatur und Drucker bei der Einteilung von I/O-Geräten?", o:["Human readable","Machine readable","Communication","Block-oriented"], a:0, e:"Human readable: zur Kommunikation mit dem Nutzer. Machine readable: Platten, Sensoren, Controller. Communication: Modems, Netzwerk."},
{t:"io", q:"Warum gibt es eine geräteunabhängige I/O-Software-Schicht?", o:["Damit Funktionen wie Pufferung, Naming und Schutz nicht in jedem Treiber stecken","Damit jedes Gerät seinen eigenen Satz von Systemaufrufen bekommt","Damit Anwendungen direkt die Register der Geräte setzen können","Damit Interrupts ohne den Kernel behandelt werden"], a:0, e:"Gemeinsames gehört an eine Stelle: einheitliche Schnittstelle, Naming, Protection, Blocking, Buffering, Allocation. Nur Gerätespezifisches steckt im Treiber."},
{t:"io", q:"Was ist asynchrones I/O?", o:["Die Anwendung startet die Operation und arbeitet weiter, bis sie benachrichtigt wird","Die Anwendung blockiert, bis die Operation abgeschlossen ist","Die Operation wird erst beim nächsten Systemstart ausgeführt","Die Operation wird ohne jede Beteiligung des Kernels ausgeführt"], a:0, e:"Windows nutzt asynchrones I/O wo möglich für bessere Performance. Synchrones I/O blockiert dagegen bis zum Abschluss."},
{t:"io", q:"Was bedeutet das I/O-Designziel „Efficiency“?", o:["I/O soll den Rest des Systems möglichst wenig ausbremsen","Alle Geräte sollen über dieselbe Schnittstelle angesprochen werden","Jedes Gerät soll seinen eigenen, optimierten Systemaufruf bekommen","I/O-Geräte sollen möglichst wenig Strom verbrauchen"], a:0, e:"I/O (vor allem Platte) ist oft der Flaschenhals. Multiprogramming, Pufferung und Disk Scheduling helfen, die CPU trotzdem auszulasten."},
{t:"io", q:"Was ist Single Buffering?", o:["Das OS nutzt einen Puffer im Systemspeicher für Ein- bzw. Ausgaben","Jeder Block wird ohne Puffer direkt in den Prozess übertragen","Zwei Puffer werden abwechselnd befüllt und verarbeitet","Ein Ringpuffer mit vielen Plätzen wird reihum genutzt"], a:0, e:"Das OS kann z. B. schon den nächsten Block lesen (Read-ahead), während der Prozess den vorigen verarbeitet. Double Buffering nutzt zwei Puffer, Circular Buffering mehr als zwei."},
{t:"io", q:"Warum puffert das OS Daten bei I/O überhaupt?", o:["Um Tempo-Unterschiede zwischen Prozess und Gerät auszugleichen","Um Daten dauerhaft zu sichern, falls die Platte ausfällt","Um Daten vor dem Lesen zu verschlüsseln","Um zu verhindern, dass Geräte Interrupts auslösen"], a:0, e:"Ohne Puffer müsste ein Prozess bei jedem Block warten, und Seiten mit I/O-Ziel dürften nicht ausgelagert werden. Puffer entkoppeln Prozess und Gerät."},
{t:"io", q:"Was ist Circular Buffering?", o:["Mehr als zwei Puffer werden reihum befüllt und geleert","Ein einziger Puffer wird immer wieder überschrieben","Daten werden zwischen zwei Platten im Kreis kopiert","Der Puffer wird bei jedem Zugriff komplett geleert"], a:0, e:"Sinnvoll, wenn ein Prozess schnelle I/O-Bursts hat: Mehrere Puffer fangen Spitzen ab. Entspricht dem Producer-Consumer-Modell mit begrenztem Puffer."},
{t:"io", q:"Was ist die Seek Time bei einer Festplatte?", o:["Die Zeit, bis der Kopf auf der richtigen Spur steht","Die Zeit, bis der richtige Sektor unter dem Kopf ist","Die Zeit für die eigentliche Datenübertragung","Die Zeit, bis die Platte nach dem Einschalten bereit ist"], a:0, e:"Zugriffszeit = Seek Time + Rotational Delay + Transfer Time. Die Seek Time ist meist der größte Anteil – deshalb gibt es Disk-Scheduling-Verfahren."},
{t:"io", q:"Was macht Disk Scheduling mit SSTF (Shortest Service Time First)?", o:["Es bedient die Anfrage, deren Spur am nächsten zur aktuellen Kopfposition liegt","Es bedient die Anfragen strikt in Ankunftsreihenfolge","Es fährt den Kopf in eine Richtung und bedient alles auf dem Weg","Es bedient zuerst die Anfrage mit der kleinsten Datenmenge"], a:0, e:"SSTF minimiert die Kopfbewegung pro Schritt, kann aber Anfragen am Rand verhungern lassen."},
{t:"io", q:"Wie funktioniert der SCAN-Algorithmus (Elevator) beim Disk Scheduling?", o:["Der Kopf fährt in eine Richtung, bedient alles auf dem Weg und kehrt am Ende um","Der Kopf springt immer zur nächstgelegenen Anfrage","Der Kopf bedient die Anfragen in der Reihenfolge ihrer Ankunft","Der Kopf bleibt stehen, bis genug Anfragen für eine Spur gesammelt sind"], a:0, e:"Wie ein Aufzug: Keine Starvation wie bei SSTF. C-SCAN fährt nur in eine Richtung und springt dann zurück – das sorgt für gleichmäßigere Wartezeiten."},
{t:"io", q:"Warum ist Disk Scheduling bei Festplatten wichtig?", o:["Kopfbewegungen sind langsam, die Reihenfolge spart viel Zeit","Weil Festplatten nur eine Anfrage pro Sekunde annehmen","Weil sonst Daten auf der Platte überschrieben werden","Weil die CPU sonst keine Interrupts der Platte erhält"], a:0, e:"Die Seek Time liegt im Millisekundenbereich – Ewigkeiten im Vergleich zur CPU. Bei SSDs ohne bewegliche Teile spielt Disk Scheduling eine viel kleinere Rolle."},
{t:"io", q:"Was bedeutet Write Penalty bei RAID 4/5?", o:["Jeder kleine Schreibvorgang muss auch die Paritätsinformation lesen und neu schreiben","Daten dürfen nur auf eine einzige Platte des Arrays geschrieben werden","Schreibvorgänge sind verboten, solange eine Platte ausgefallen ist","Jeder Schreibvorgang wird zur Sicherheit auf alle Platten gespiegelt"], a:0, e:"Für eine kleine Änderung: alten Datenblock und alte Parität lesen, neue Parität berechnen, beides schreiben. RAID 4 hat dadurch einen Flaschenhals auf der Paritätsplatte; RAID 5 verteilt die Last."},
// ---------- Erweiterung: Virtualisierung ----------
{t:"virt", q:"Was versteht man unter Virtualisierung?", o:["Mehrere isolierte Umgebungen teilen sich dieselbe physische Hardware","Ein Programm wird in eine andere Programmiersprache übersetzt","Daten werden auf mehrere Rechenzentren verteilt gespiegelt","Der Arbeitsspeicher wird durch die Festplatte vollständig ersetzt"], a:0, e:"Jede VM glaubt, eine eigene Maschine zu haben. Vorteile: bessere Auslastung, Isolation, einfache Migration und Backups."},
{t:"virt", q:"Warum ist ein Type-1-Hypervisor meist effizienter als ein Type-2-Hypervisor?", o:["Er läuft direkt auf der Hardware, ohne Umweg über ein Host-Betriebssystem","Er führt die Gast-Betriebssysteme komplett ohne Traps aus","Er braucht keine Gerätetreiber, weil die Hardware alles selbst erledigt","Er erlaubt nur eine einzige VM und hat daher keinen Overhead"], a:0, e:"Bei Type 2 gehen Hardwarezugriffe zusätzlich durch das Host-OS. Type 1 (ESXi, Xen, Hyper-V) ist daher typisch für Server."},
{t:"virt", q:"Wofür eignet sich ein Type-2-Hypervisor typischerweise?", o:["Für Entwickler oder Nutzer, die auf dem Desktop eine VM neben ihren Programmen nutzen","Für große Rechenzentren mit vielen gleichzeitigen Produktions-VMs","Für Echtzeitsysteme mit harten Deadlines","Für Geräte ganz ohne Betriebssystem"], a:0, e:"Beispiele: VirtualBox, UTM, VMware Workstation – einfach zu installieren wie eine normale Anwendung."},
{t:"virt", q:"Was ist volle Virtualisierung (Full Virtualization)?", o:["Unveränderte Gast-OS laufen; sensitive Instruktionen werden abgefangen und emuliert","Das Gast-OS wird angepasst und ruft den Hypervisor direkt auf","Alle Container teilen sich den Kernel des Hosts","Die CPU wird komplett in Software nachgebildet, ohne echte Hardware"], a:0, e:"Der Gast merkt nichts von der Virtualisierung (Trap-and-Emulate oder Binary Translation). Gegenstück: Paravirtualisierung mit angepasstem Gast."},
{t:"virt", q:"Was ist Page Sharing bei VMs?", o:["Identische Speicherseiten mehrerer VMs werden nur einmal im RAM gehalten","Eine VM leiht einer anderen dauerhaft einen Teil ihres RAMs","Seiten einer VM werden auf die Platte eines anderen Hosts ausgelagert","Alle VMs teilen sich eine gemeinsame Page Table"], a:0, e:"Laufen z. B. zehn VMs mit demselben Gast-OS, sind viele Seiten gleich. Der Hypervisor erkennt sie und hält sie einmal (Copy-on-Write bei Änderung)."},
{t:"virt", q:"Was ist Memory Overcommit?", o:["Den VMs zusammen wird mehr RAM zugeteilt, als physisch vorhanden ist","Eine VM nutzt mehr CPU-Kerne, als der Host besitzt","Der Hypervisor reserviert für sich selbst den meisten Speicher","Eine VM bekommt garantiert ihren gesamten RAM exklusiv"], a:0, e:"Funktioniert, weil VMs selten ihren ganzen RAM gleichzeitig nutzen. Techniken wie Page Sharing und Ballooning machen es möglich."},
{t:"virt", q:"Was ist ein Nachteil der Abstraktion des I/O-Pfads bei VMs?", o:["Der Hypervisor muss allen Datenverkehr verwalten, das kostet Prozessorzeit","VMs können dadurch nicht mehr auf andere Hosts migriert werden","Jede VM braucht eine eigene physische Netzwerkkarte","Gast-Betriebssysteme brauchen herstellerspezifische Treiber"], a:0, e:"Vorteile: Hardwareunabhängigkeit, Live Migration, gemeinsame Nutzung von Pfaden. Preis: zusätzlicher Overhead im Hypervisor."},
{t:"virt", q:"Was ist ein Container?", o:["Eine isolierte Umgebung für Anwendungen, die den Kernel des Hosts mitbenutzt","Eine vollständige VM mit eigenem Gast-Betriebssystem","Ein Hypervisor, der direkt auf der Hardware läuft","Ein Archiv, in dem Programme komprimiert verschickt werden"], a:0, e:"Isolation über Kernel-Mechanismen (Namespaces, cgroups). Startet in Sekunden, braucht wenig Speicher – aber alle Container müssen zum Host-Kernel passen."},
{t:"virt", q:"Was ist ein Nachteil von Containern gegenüber VMs?", o:["Schwächere Isolation, da alle Container denselben Kernel teilen","Sie starten deutlich langsamer als virtuelle Maschinen","Sie brauchen für jede Anwendung ein komplettes Gast-OS","Sie können keine Netzwerkverbindungen öffnen"], a:0, e:"Eine Kernel-Lücke betrifft alle Container. Außerdem kann man z. B. keinen Windows-Container auf einem Linux-Kernel betreiben."},
{t:"virt", q:"Warum passen Microservices gut zu Containern?", o:["Jeder Service wird als leichte, eigenständige Einheit deployt","Weil Container nur einen einzigen Prozess pro Rechner erlauben","Weil Microservices zwingend ein eigenes Gast-OS brauchen","Weil Container alle Services fest zu einem Programm verbinden"], a:0, e:"Container starten schnell und brauchen wenig Ressourcen – ideal, um einzelne Services unabhängig zu deployen und bei Last zu replizieren."},
{t:"virt", q:"Was ist ein Nachteil von Microservices?", o:["Mehr Netzwerkkommunikation und schwierigeres Debugging über viele Dienste","Jede Änderung erfordert ein Neu-Deployment der gesamten Anwendung","Einzelne Teile lassen sich nicht unabhängig skalieren","Alle Services müssen in derselben Programmiersprache geschrieben sein"], a:0, e:"Aufrufe über das Netz sind langsamer und können fehlschlagen; Fehler verteilen sich über viele Dienste. Das ist der Preis für unabhängiges Deployment und Skalierung."},
{t:"virt", q:"Was ist ein Monolith im Sinne der Softwarearchitektur?", o:["Eine Anwendung, die als ein großes Ganzes entwickelt und deployt wird","Eine Anwendung aus vielen unabhängig deploybaren Diensten","Ein Betriebssystem mit Microkernel","Ein Container, der nur eine einzige Datei enthält"], a:0, e:"Gegenmodell zu Microservices: einfacher zu entwickeln und zu debuggen, aber jede Änderung betrifft das ganze Deployment, und skaliert wird nur als Ganzes."},
{t:"virt", q:"Was ist Java-Bytecode?", o:["Ein plattformunabhängiger Zwischencode, den die JVM ausführt","Maschinencode, der direkt auf der CPU läuft","Der Quellcode eines Java-Programms","Ein Konfigurationsformat für Java-Anwendungen"], a:0, e:"Der Compiler erzeugt Bytecode (.class). Die JVM interpretiert ihn oder übersetzt ihn per JIT in Maschinencode – so gilt „einmal schreiben, überall ausführen“."},
{t:"virt", q:"Was unterscheidet eine Process VM wie die JVM von einer System-VM?", o:["Die JVM führt ein einzelnes Programm aus, eine System-VM ein ganzes Betriebssystem","Die JVM läuft direkt auf der Hardware, eine System-VM als Anwendung","Die JVM braucht einen Type-1-Hypervisor, eine System-VM nicht","Es gibt keinen Unterschied, beide virtualisieren die komplette Hardware"], a:0, e:"Die JVM ist ein normaler Prozess auf dem Host-OS, der eine abstrakte Maschine für Bytecode bereitstellt. Eine System-VM (unter einem Hypervisor) bildet einen ganzen Rechner nach."},
{t:"virt", q:"Was ist Dom0 bei Xen?", o:["Die privilegierte Verwaltungsdomäne mit den Gerätetreibern","Eine unprivilegierte Gast-VM ohne direkten Hardwarezugriff","Der Bootloader, der Xen beim Systemstart lädt","Der Kommunikationskanal zwischen zwei Gast-VMs"], a:0, e:"Dom0 verwaltet die anderen VMs (DomU) und stellt ihnen Geräte über ihre Treiber bereit. Bei Hyper-V heißt das Gegenstück Parent Partition."},
// ---------- Erweiterung: Distributed Systems ----------
{t:"dist", q:"Welche Garantien bietet TCP?", o:["Zuverlässige Zustellung in richtiger Reihenfolge","Schnellste Übertragung ohne Verbindungsaufbau","Feste Übertragungsdauer für jedes einzelne Paket","Verschlüsselung aller übertragenen Daten"], a:0, e:"TCP ist verbindungsorientiert, erkennt Verluste, sendet neu, sortiert und hat Flow und Congestion Control. Verschlüsselung kommt erst durch TLS."},
{t:"dist", q:"Warum braucht TCP einen 3-Way-Handshake?", o:["Beide Seiten prüfen Empfangsbereitschaft und Sequenznummern","Damit die Daten vor dem Senden verschlüsselt werden","Damit der Server die IP-Adresse des Clients herausfindet","Damit die Pakete den kürzesten Weg durch das Netz nehmen"], a:0, e:"SYN (Client schlägt Sequenznummer vor) → SYN-ACK (Server bestätigt und schlägt eigene vor) → ACK (Client bestätigt). Danach ist die Verbindung in beide Richtungen bereit."},
{t:"dist", q:"Wie erkennt TCP verlorene Pakete?", o:["Über ausbleibende Bestätigungen (ACKs) und Timeouts","Über eine Prüfsumme, die der Router meldet","Gar nicht – das muss die Anwendung erledigen","Über eine Nachricht des verlorenen Pakets selbst"], a:0, e:"Der Empfänger bestätigt erhaltene Daten anhand der Sequenznummern. Fehlt die Bestätigung bis zum Timeout (oder kommen doppelte ACKs), wird erneut gesendet."},
{t:"dist", q:"Wann ist UDP besser geeignet als TCP?", o:["Wenn geringe Verzögerung wichtiger ist als vollständige Zustellung, z. B. Video-Calls","Wenn jede Datei garantiert vollständig ankommen muss, z. B. Downloads","Wenn eine Verbindung über lange Zeit stabil bleiben soll","Wenn Daten in genau der gesendeten Reihenfolge ankommen müssen"], a:0, e:"Bei Echtzeit-Audio/Video ist ein verspätetes, neu gesendetes Paket nutzlos. UDP hat keinen Verbindungsaufbau und kein Warten auf Neuübertragung."},
{t:"dist", q:"Warum baut QUIC auf UDP statt auf einem ganz neuen Transportprotokoll auf?", o:["UDP wird von Routern und Middleboxes bereits überall durchgelassen","UDP garantiert schon Zuverlässigkeit und Reihenfolge","UDP ist das einzige Protokoll mit Verschlüsselung","UDP hat einen größeren Header für zusätzliche Informationen"], a:0, e:"Ein neues Protokoll würde von vielen Firewalls und NAT-Geräten blockiert. UDP geht durch, und QUIC baut Zuverlässigkeit, Streams und Verschlüsselung darüber selbst."},
{t:"dist", q:"Was ist eine persistente HTTP-Verbindung (Keep-Alive)?", o:["Eine TCP-Verbindung wird für mehrere Requests wiederverwendet","Für jede Ressource wird eine neue TCP-Verbindung aufgebaut","Der Server speichert den Zustand jedes Clients dauerhaft","Der Browser hält die Seite offline im Speicher"], a:0, e:"Spart wiederholte Handshakes. HTTP/1.0 baute pro Request eine Verbindung auf, HTTP/1.1 nutzt standardmäßig persistente Verbindungen."},
{t:"dist", q:"Was hat HTTP/2 gegenüber HTTP/1.1 vor allem verbessert?", o:["Mehrere Requests werden über eine Verbindung gemultiplext","Es läuft über UDP statt TCP","Es verzichtet auf den TCP-Handshake","Es löst das Head-of-Line-Blocking auf Transportebene"], a:0, e:"HTTP/2 multiplext Streams auf Anwendungsebene über eine TCP-Verbindung (dazu binäre Frames, Header-Kompression). Das TCP-HoL-Problem bleibt aber – erst HTTP/3 löst es."},
{t:"dist", q:"Was bedeutet, dass HTTP zustandslos (stateless) ist?", o:["Jeder Request ist unabhängig, der Server merkt sich nichts","Der Server speichert jede Seite nur einmal im Cache","Die Verbindung wird nach jedem Byte geschlossen","Der Client darf keine Daten speichern"], a:0, e:"Zustand (z. B. Login) wird zusätzlich über Cookies oder Tokens hergestellt. Zustandslosigkeit erleichtert Skalierung über mehrere Server."},
{t:"dist", q:"Warum hilft es bei HoL-Blocking nicht, nur die Anwendungsschicht (HTTP/2) zu ändern?", o:["TCP liefert die Bytes nur in Reihenfolge aus und hält bei Verlust alles zurück","Weil HTTP/2 grundsätzlich nur einen Stream gleichzeitig erlaubt","Weil der Server bei HTTP/2 Requests nacheinander bearbeiten muss","Weil Verschlüsselung bei HTTP/2 Pakete blockiert"], a:0, e:"Für TCP sind alle Streams ein einziger Bytestrom. Erst wenn das verlorene Paket neu da ist, gibt TCP die folgenden Bytes heraus – auch die anderer Streams."},
{t:"dist", q:"Was ist 0-RTT bei QUIC?", o:["Bekannte Server: Daten schon im ersten Paket senden","Pakete werden ohne jede Laufzeit über das Netz übertragen","Der Server antwortet, bevor der Client etwas gesendet hat","Die Verbindung kommt ganz ohne Verschlüsselung aus"], a:0, e:"QUIC kombiniert Transport- und TLS-Handshake (1-RTT). Kennt der Client den Server schon, kann er Daten direkt im ersten Paket mitschicken – weniger Handshakes als TCP + TLS."},
{t:"dist", q:"Warum verursacht die Verschlüsselung von QUIC Probleme für Netzbetreiber?", o:["Firewalls und Monitoring können die Metadaten nicht mehr einsehen","Verschlüsselte Pakete sind zu groß für normale Router","Verschlüsselung verhindert, dass Pakete überhaupt ankommen","Netzbetreiber müssen für jede Verbindung einen Schlüssel ausstellen"], a:0, e:"Was bei TCP sichtbar war (z. B. Sequenznummern), ist bei QUIC verschlüsselt. Das schützt Nutzer und erschwert Ossifikation, macht aber Analyse und Fehlersuche im Netz schwerer."},
{t:"dist", q:"Was passiert, wenn ein Netz UDP blockiert und ein Browser HTTP/3 nutzen will?", o:["Der Browser fällt auf HTTP/2 über TCP zurück","Die Seite kann gar nicht geladen werden","Der Browser schickt QUIC dann über ICMP","Der Server schaltet automatisch auf UDP-Broadcast um"], a:0, e:"Browser versuchen HTTP/3 meist parallel und nutzen sonst TCP. Das ist eine der offenen Herausforderungen von HTTP/3."},
{t:"dist", q:"Was ist ein verteiltes System?", o:["Mehrere unabhängige Rechner, die dem Nutzer wie ein einziges System erscheinen","Ein Rechner mit mehreren Prozessoren und gemeinsamem Speicher","Ein Programm, das auf mehrere Threads verteilt ist","Ein Netzwerk, in dem jeder Rechner völlig isoliert arbeitet"], a:0, e:"Die Rechner haben eigenen Speicher und kommunizieren über Nachrichten im Netz. Ziel ist Transparenz: Der Nutzer soll die Verteilung nicht merken."},
{t:"dist", q:"Was bedeutet Transparenz in einem verteilten System?", o:["Die Verteilung auf mehrere Rechner bleibt für den Nutzer verborgen","Alle Daten sind für jeden Nutzer frei einsehbar","Der Quellcode des Systems ist öffentlich verfügbar","Jede Nachricht wird zur Kontrolle an alle Rechner geschickt"], a:0, e:"Arten: Orts-, Zugriffs-, Replikations-, Fehler-, Migrationstransparenz. Beispiel: Eine Datei öffnen, ohne zu wissen, auf welchem Server sie liegt."},
{t:"dist", q:"Was ist das Client-Server-Modell?", o:["Clients schicken Anfragen, ein Server bearbeitet sie und antwortet","Alle Rechner sind gleichberechtigt und tauschen direkt Daten aus","Ein Server schickt Daten unaufgefordert an alle Clients","Clients und Server laufen immer auf demselben Rechner"], a:0, e:"Beispiel: Browser (Client) und Web-Server. Gegenmodell: Peer-to-Peer, bei dem alle Knoten gleichberechtigt sind."},
{t:"dist", q:"Was ist ein Remote Procedure Call (RPC)?", o:["Der Aufruf einer Funktion auf einem anderen Rechner, als wäre sie lokal","Ein Systemaufruf, der in den Kernel des eigenen Rechners führt","Das Starten eines neuen Prozesses auf dem eigenen Rechner","Eine Nachricht, mit der ein Server seine Clients beendet"], a:0, e:"Ein Stub verpackt die Parameter in eine Nachricht (Marshalling), schickt sie übers Netz und gibt das Ergebnis zurück – der Netzwerkverkehr bleibt dem Programmierer verborgen."}
];
